.php","displayUrl":"https://github.com/lazymofo/datagrid/blob/master/lazy_mofo.php?raw=true","headerInfo":{"blobSize":"109 KB","deleteTooltip":"Fork this repository and delete the file","editTooltip":"Fork this repository and edit the file","ghDesktopPath":"https://desktop.github.com","isGitLfs":false,"onBranch":true,"shortPath":"bcd7526","siteNavLoginPath":"/login?return_to=https%3A%2F%2Fgithub.com%2Flazymofo%2Fdatagrid%2Fblob%2Fmaster%2Flazy_mofo.php","isCSV":false,"isRichtext":false,"lineInfo":{"truncatedLoc":"2847","truncatedSloc":"2023"},"mode":"file"},"image":false,"isCodeownersFile":null,"isPlain":false,"isValidLegacyIssueTemplate":false,"isIssueTemplate":false,"isDiscussionTemplate":false,"language":"PHP","languageID":272,"large":false,"planSupportInfo":{"repoIsFork":null,"repoOwnedByCurrentUser":null,"requestFullPath":"/lazymofo/datagrid/blob/master/lazy_mofo.php","showFreeOrgGatedFeatureMessage":null,"showPlanSupportBanner":null,"upgradeDataAttributes":null,"upgradePath":null},"publishBannersInfo":{"dismissActionNoticePath":"/settings/dismiss-notice/publish_action_from_dockerfile","releasePath":"/lazymofo/datagrid/releases/new?marketplace=true","showPublishActionBanner":false},"rawBlobUrl":"https://github.com/lazymofo/datagrid/raw/refs/heads/master/lazy_mofo.php","renderImageOrRaw":false,"shortPath":null,"symbolsEnabled":true,"tabSize":4,"topBannersInfo":{"overridingGlobalFundingFile":false,"globalPreferredFundingPath":null,"showInvalidCitationWarning":false,"citationHelpUrl":"https://docs.github.com/github/creating-cloning-and-archiving-repositories/creating-a-repository-on-github/about-citation-files","actionsOnboardingTip":null},"truncated":false,"viewable":true,"workflowRedirectUrl":null},"copilotInfo":null,"copilotAccessAllowed":true,"copilotSpacesEnabled":true,"modelsAccessAllowed":false,"modelsRepoIntegrationEnabled":false,"isMarketplaceEnabled":true},"codeViewBlobLayoutRoute.StyledBlob":{"rawLines":["\u003c?php\r","\r","// CRUD datagrid for MySQL and PHP\r","// MIT License - https://github.com/lazymofo/datagrid\r","// send feedback or questions iansoko at gmail\r","// version 2023-11-22 \r","\r","class lazy_mofo{\r","\r","    public $dbh = false;                    // required, pass the PDO connection object into the constructor\r","    public $table = '';                     // required, table for use for sql_insert(), sql_update(), sql_update_grid() and sql_delete()\r","    public $identity_name = '';             // required, column name of id primary key \r","\r","    public $rename = array();               // associative array of column names and friendly names. example: array('prod_id' =\u003e 'Product ID') \r","\r","    public $uri_path = '';                  // experimental - to specify URI used for WordPress admin plugins, example: http://localhost:80/demo.php\r","\r","    public $absolute_redirect = false;      // 2018-06 switched to relative redirects since it should be supported now, also port forwards don't work with absolute redirects \r","\r","    public $query_string_list = '';         // comma delimited list of variable names to carry around in the URL\r","\r","    public $exclude_field = array();        // don't allow users to update or insert into these fields, even if data is posted. place the field name in the key of the array. example: $lm-\u003eexclude_field['is_admin'] = '';\r","\r","    public $form_sql = '';                  // render form from fields retuned in sql statement. if blank then 'select * from table where identity_name = identity_id' is used. when no record is found then a blank form to ADD a record is displayed\r","    public $form_sql_param = array();       // associative array to bind named parameters to form_sql. use to pass in identity_id when specifiying form_sql.\r","    public $form_input_control = array();   // for form(), define inputs like select boxes, checkboxes, etc. example: $lm-\u003eform_input_control['field_name'] = array('type' =\u003e 'select', 'sql' =\u003e \"select id as val, title as opt from table\");\r","    public $form_default_value = array();   // for form(), define default values for columns when adding a record. if auto_populate_control = true then this array will be populated from the defaults in the database. \r","    public $form_display_identity = true;   // display identity value when editing a record\r","    public $form_additional_html = '';      // add any addition html inside the \u003cform\u003e after the form buttons.\r","    public $form_text_input_size = 35;      // size of text inputs on form()\r","\r","    public $grid_sql = '';                  // optional, render grid with query result. *important* to display [edit] and [delete] links, the identity must be the last column in the sql statement. include an 'order by' to prevent query parsing errors on complex queries.\r","    public $grid_sql_param = array();       // associative array to bind variables to grid_sql. example: $lm-\u003egrid_sql_param(':market_id' =\u003e $market_id);\r","    public $grid_default_order_by = '';     // free-form 'order by' clause. Not used if grid_sql is specified. Example: column1 desc, column2 asc\r","    public $grid_input_control = array();   // for grid(), define inputs like select boxes, checkboxes, etc. example: $lm-\u003egrid_input_control['field_name'] = array('type' =\u003e 'select', 'sql' =\u003e \"select id as val, title as opt from table\");\r","    public $grid_output_control = array();  // for grid(). define outputs like email or document to make a link. example: example: $lm-\u003egrid_output_control['field_name'] = array('type' =\u003e 'email');\r","    public $grid_multi_delete = false;      // display checkboxes on grid to allow for multiple record delete\r","    public $grid_show_search_box = false;   // display search field at the top - grid_sql must be altered to accomodate search\r","    public $grid_limit = 200;               // pagination limit number of records per page, verion \u003e= 2018-07-10 set to 0 to disable pagination\r","    public $grid_repeat_header_at = 0;      // interval of records to repeat header column titles at\r","    public $grid_show_images = false;       // option to show images inside the grid, otherwise a link is displayed for --image type\r","    public $grid_ellipse_at = 30;           // limit number of characters displayed, set to 0 to disable truncation\r","    public $grid_text_input_size = 10;      // size of text input when input is displayed\r","\r","    public $text_input_max_length_default = 0;  // global max_length attribute for input. 0 is disabled\r","    public $text_input_max_length = array();    // array of column names to max length integers, optional\r","\r","    public $auto_populate_controls = true;      // have get_columns() populate input and output controls according to meta data for types --date, --datetime, --number and --textarea. also, populate default values if user has read access to information_schema.columns\r","\r","    public $on_insert_validate = array();       // example : array('regexp' =\u003e '/.+/', 'error_msg' =\u003e 'Missing Market Name', 'placeholder' =\u003e 'this is required', 'optional' =\u003e false); \r","    public $on_update_validate = array();       // regexp may be 'email' or a user defined function, all other parameters optional\r","    public $validate_tip_in_placeholder = true; // allow input placeholder to display validation tip\r","\r","    public $on_insert_user_function = '';       // user function called before data is inserted, updated, or deleteed. return a string error message for server-side validation. Can be used to formating _POST data.\r","    public $on_update_user_function = '';\r","    public $on_delete_user_function = '';\r","    public $on_update_grid_user_function = '';\r","\r","    public $after_insert_user_function = '';    // user function names to be called after data is inserted, updated, or deleted.\r","    public $after_update_user_function = '';\r","    public $after_delete_user_function = '';\r","    public $after_update_grid_user_function = '';\r","\r","    public $cast_user_function = array();       // user function for casting data, example : $lm-\u003ecast_function['field_name'] = 'my_casting_function'\r","\r","    public $return_to_edit_after_insert = true; // redirect to edit screen after adding or updating a record. if false, user is sent back to grid view.\r","    public $return_to_edit_after_update = true; \r","\r","    public $redirect_using_js = false;          // redirect to a page using java-script instead of header modification by means of PHP. \r","\r","    public $charset_mysql = 'utf8mb4';          // charset for mysql communications. was utf8 before version 2017-08-31 \r","    public $charset = 'UTF-8';                  // charset for output\r","\r","    public $timezone = 'UTC';                   // if no timezone is set in the application, then this timezone is set for strtotime. http://php.net/manual/en/timezones.others.php\r","\r","    // image settings    \r","    public $upload_width = 400;                 // 0 height or width means no resizing or cropping\r","    public $upload_height = 400;\r","    public $upload_crop = false;                // crop versus resize: resize keeps the original aspect ratio but limits the size of the image\r","    public $thumb_width = 100;\r","    public $thumb_height = 100;\r","    public $thumb_crop = true;\r","\r","    public $image_quality = 80;                       // image quality when resizing and cropping, 1-100\r","    public $image_style = \"style='height: 100px;'\";   // apply style to all images displayed. limiting size is nice to keep things orderly.\r","\r","    public $decimal_separator = '.';                   // expected separator for incoming number, use format() in grid_sql or form_sql for output values, example: \"select format(12.34, 2, 'es_ES') as num;\"    \r","    public $restricted_numeric_input = '/[^0-9\\.\\-]/'; // do not change - input filter into database, minus could be removed if all numbers are unsigned\r","\r","    public $upload_allow_list = '.mp3 .jpg .jpeg .png .gif .doc .docx .xls .xlsx .txt .pdf'; // space delimted file name extentions. include period\r","\r","    public $export_csv_file_name = '';\r","    public $export_separator = ',';                  // separator for csv export\r","    public $export_delim = '\"';                      // delimiter for csv export \r","    public $export_delim_escape = '\"';               // if delim is used in content add this string before for escaping\r","\r","    public $delim = '|';                             // when using mutiple checkboxes or multipleselect, delimiter for values. to store data non delimited use on_insert_user_function and on_update_user_function to save data.\r","\r","    public $select_first_option_blank = true;        // make first option blank on dropdown select and selectmultiple inputs\r","\r","    // start i18n defaults // \r","\r","    // javascript dialogs\r","    public $delete_confirm      = 'Are you sure you want to delete this record?';\r","    public $update_grid_confirm = 'Are you sure you want to delete [count] record(s)?';\r","\r","    // validation general error - this is displayed at the top when a validation error occurs\r","    public $validate_text_general = \"Missing or Invalid Input\";\r","\r","    // form buttons\r","    public $form_add_button    = \"\u003cinput type='submit' value='Add' class='lm_button'\u003e\";\r","    public $form_update_button = \"\u003cinput type='submit' value='Update' class='lm_button'\u003e\"; \r","    public $form_back_button   = \"\u003cinput type='button' value='\u0026lt; Back' class='lm_button dull' onclick='_back();'\u003e\";\r","    public $form_delete_button = \"\u003cinput type='button' value='Delete' class='lm_button error' onclick='_delete();'\u003e\"; \r","\r","    // titles in the \u003cth\u003e of top of the edit form \r","    public $form_text_title_add    = 'Add Record';   \r","    public $form_text_title_edit   = 'Edit Record';\r","    public $form_text_record_saved = 'Record Saved';\r","    public $form_text_record_added = 'Record Added';\r","\r","    // links on grid\r","    public $grid_add_link    = \"\u003ca href='[script_name]action=edit\u0026amp;[qs]' class='lm_grid_add_link'\u003eAdd a Record\u003c/a\u003e\";\r","    public $grid_edit_link   = \"\u003ca href='[script_name]action=edit\u0026amp;[identity_name]=[identity_id]\u0026amp;[qs]'\u003e[edit]\u003c/a\u003e\";\r","    public $grid_delete_link = \"\u003ca href='#' onclick='return _delete(\\\"[identity_id]\\\");'\u003e[delete]\u003c/a\u003e\";\r","    public $grid_export_link = \"\u003ca href='[script_name]_export=1\u0026amp;[qs]' title='Download CSV'\u003eExport\u003c/a\u003e\";\r","\r","    // search box\r","    public $grid_search_box = \"\u003cform action='[script_name]' class='lm_search_box'\u003e\u003cinput type='text' name='_search' value='[_search]' size='20' class='lm_search_input'\u003e\u003ca href='[script_name]' style='margin: 0 10px 0 -20px; display: inline-block;' title='Clear Search'\u003ex\u003c/a\u003e\u003cinput type='submit' class='lm_button lm_search_button' value='Search'\u003e\u003cinput type='hidden' name='action' value='search'\u003e[query_string_list]\u003c/form\u003e\"; \r","\r","    // grid messages\r","    public $grid_text_record_added     = \"Record Added\";\r","    public $grid_text_changes_saved    = \"Changes Saved\";\r","    public $grid_text_record_deleted   = \"Record Deleted\";\r","    public $grid_text_save_changes     = \"Save Changes\";\r","    public $grid_text_delete           = \"Delete\";\r","    public $grid_text_no_records_found = \"No Records Found\";\r","\r","    // pagination text\r","    public $pagination_text_use_paging = 'use paging';\r","    public $pagination_text_show_all   = 'show all';\r","    public $pagination_text_records    = 'Record(s)';\r","    public $pagination_text_go         = 'Go';\r","    public $pagination_text_page       = 'Page';\r","    public $pagination_text_of         = 'of';\r","    public $pagination_text_next       = 'Next\u0026gt;';\r","    public $pagination_text_back       = '\u0026lt;Back';\r","\r","    // delete upload link text\r","    public $text_delete_image = 'delete image';\r","    public $text_delete_document = 'delete document';\r","\r","    // relative paths for image or documents uploads\r","    // all paths are created at runtime as needed\r","    public $upload_path = 'uploads';            // required when using input types\r","    public $thumb_path = 'thumbs';              // optional, leave blank if you don't need thumbnails\r","\r","    // newly added absolute paths, 2019-09\r","    // if absolute paths are defined then files are uploaded here, relative paths always used on the client side\r","    public $upload_path_absolute = '';          // optional, defaults to $upload_path if not defined\r","    public $thumb_path_absolute = '';           // optional, defaults to $thumb_path if not defined\r","\r","    // output date formats\r","    public $date_out = 'm/d/Y';                 // output date, change to d/m/Y for non-us\r","    public $datetime_out = 'm/d/Y h:i A';       // output datetime, change to d/m/Y h:i A for non-us\r","\r","    // end i18n defaults // \r","\r","    public $date_in = 'Y-m-d';                  // do not change - input format into database\r","    public $datetime_in = 'Y-m-d H:i:s';        // do not change\r","    private $set_names = false;                 // do not change - internal flag\r","\r","    function __construct($dbh, $i18n = 'en-us'){\r","\r","        if(!$dbh)\r","            die('Pass in a PDO object connected to the mysql database.');\r","\r","        $this-\u003edbh = $dbh; \r","\r","        $timezone = @date_default_timezone_get();\r","        if($timezone == '' || $timezone == 'UTC')\r","            date_default_timezone_set($this-\u003etimezone);\r","\r","        if(!extension_loaded('mbstring'))\r","            die(\"Error: php mbstring module required - please install\");\r","\r","        // avoid notices for this noonce token\r","        if(!isset($_SESSION['_csrf']))\r","            $_SESSION['_csrf'] = '';\r","\r","        // load requested internationalization file, en-us is defined above, in this class\r","        if(strlen($i18n) \u003e 0 \u0026\u0026 $i18n != 'en-us'){\r","            $arr = pathinfo(__FILE__);\r","            $path = $arr['dirname'] . \"/i18n/{$i18n}.php\";\r","            if(!file_exists($path))\r","                die(\"Error: Requested file $path does not exists.\");\r","            include($path);    \r","        }\r","\r","    }\r","\r","    \r","    function run(){\r","\r","        // purpose: controller \r","\r","        // change controls into newer format\r","        foreach($this-\u003eform_input_control as $column_name =\u003e $control)\r","            $this-\u003eform_input_control[$column_name] = $this-\u003emodernize_control($control, $column_name);\r","        foreach($this-\u003egrid_input_control as $column_name =\u003e $control)\r","            $this-\u003egrid_input_control[$column_name] = $this-\u003emodernize_control($control, $column_name);\r","        foreach($this-\u003egrid_output_control as $column_name =\u003e $control)\r","            $this-\u003egrid_output_control[$column_name] = $this-\u003emodernize_control($control, $column_name);\r","\r","        // change validation into newer format with keys\r","        foreach($this-\u003eon_insert_validate as $column_name =\u003e $arr)\r","            $this-\u003eon_insert_validate[$column_name] = $this-\u003emodernize_validate($arr, $column_name);\r","        foreach($this-\u003eon_update_validate as $column_name =\u003e $arr)\r","            $this-\u003eon_update_validate[$column_name] = $this-\u003emodernize_validate($arr, $column_name);\r","\r","        switch($this-\u003eget_action()){\r","            case \"edit\":          $this-\u003eedit();        break;\r","            case \"insert\":        $this-\u003einsert();      break;\r","            case \"update\":        $this-\u003eupdate();      break;\r","            case \"update_grid\":   $this-\u003eupdate_grid(); break;\r","            case \"delete\":        $this-\u003edelete();      break;\r","            default:              $this-\u003eindex();\r","        }\r","\r","    }\r","\r","    \r","    function edit($error = ''){\r","\r","        // purpose: called from contoller to display form() and add or edit a record\r","\r","        echo $this-\u003eform($error);\r","\r","    }\r","\r","\r","    function insert(){\r","\r","        // purpose: called from contoller to display insert() data\r","        \r","        $error = '';\r","\r","        // validation system\r","        $is_valid = $this-\u003evalidate($this-\u003eon_insert_validate);\r","        if(!$is_valid)\r","            $error = $this-\u003evalidate_text_general; //optional general error at the top\r","\r","        // call user function to validate or whatever\r","        if($is_valid \u0026\u0026 $this-\u003eon_insert_user_function != '')\r","            $error = call_user_func($this-\u003eon_insert_user_function);\r","\r","        // go back on validation error\r","        if($error != '' || !$is_valid){\r","            $this-\u003eedit($error);\r","            return;\r","        }\r","\r","        // insert data\r","        $id = $this-\u003esql_insert();\r","\r","        // user function after insert\r","        if($this-\u003eafter_insert_user_function != '')\r","            call_user_func($this-\u003eafter_insert_user_function, $id);\r","        \r","        // send user back to edit screen if desired\r","        $action = '';\r","        if($this-\u003ereturn_to_edit_after_insert)\r","            $action = 'action=edit\u0026';\r","\r","        // redirect user\r","        $url = $this-\u003eget_uri_path() . \"{$action}_success=1\u0026$this-\u003eidentity_name=$id\u0026\" . $this-\u003eget_qs(''); // do carry items defined in query_string_list, '' removes the default\r","        $this-\u003eredirect($url, $id);\r","\r","    }\r","\r","\r","    function update(){\r","\r","        // purpose: called from contoller to display update() data\r","\r","        $error = '';\r","\r","        // validation system\r","        $is_valid = $this-\u003evalidate($this-\u003eon_update_validate);\r","\r","        if(!$is_valid)\r","            $error = $this-\u003evalidate_text_general; //optional general error at the top\r","\r","        // call user function to validate or whatever\r","        if($is_valid \u0026\u0026 $this-\u003eon_update_user_function != '')\r","            $error = call_user_func($this-\u003eon_update_user_function);\r","\r","        // go back on validation error\r","        if($error != '' || !$is_valid){\r","            $this-\u003eedit($error);\r","            return;\r","        }\r","\r","        // update data\r","        $id = $this-\u003esql_update();\r","\r","        // user function after update\r","        if($this-\u003eafter_update_user_function != '')\r","            call_user_func($this-\u003eafter_update_user_function);\r","        \r","        // send user back to edit screen if desired\r","        $action = '';\r","        if($this-\u003ereturn_to_edit_after_update)\r","            $action = 'action=edit\u0026';\r","\r","        // redirect user\r","        $url = $this-\u003eget_uri_path() . \"{$action}_success=2\u0026$this-\u003eidentity_name=$id\u0026\" . $this-\u003eget_qs();\r","        $this-\u003eredirect($url, $id);\r","\r","    }\r","\r","\r","    function update_grid(){\r","\r","        // purpose: called from contoller to display update() data\r","\r","        // call user function to validate or whatever\r","        $error = '';\r","        if($this-\u003eon_update_grid_user_function != '')\r","            $error = call_user_func($this-\u003eon_update_grid_user_function);\r","\r","        // go back on validation error\r","        if($error != ''){\r","            $this-\u003eindex($error);\r","            return;\r","        }\r","        \r","        // update data\r","        $flag = $this-\u003esql_update_grid();\r","\r","        // user function after updates\r","        if($this-\u003eafter_update_grid_user_function != '')\r","            call_user_func($this-\u003eafter_update_grid_user_function);\r","\r","        // redirect user\r","        $url = $this-\u003eget_uri_path() . \"_success=2\u0026\" . $this-\u003eget_qs();\r","        $this-\u003eredirect($url, $flag);\r","\r","    }\r","\r","\r","    function delete(){\r","\r","        // purpose: called from contoller to display update() data\r","\r","        // call user function to validate or whatever\r","        $error = '';\r","        if($this-\u003eon_delete_user_function != '')\r","            $error = call_user_func($this-\u003eon_delete_user_function);\r","\r","        // go back on validation error\r","        if($error != ''){\r","            if(($_POST['_called_from'] ?? '') == 'form')\r","                $this-\u003eedit($error);\r","            else\r","                $this-\u003eindex($error);\r","\r","            return;\r","        }\r","        \r","        // delete data\r","        $flag = $this-\u003esql_delete();\r","\r","        // user function after delete\r","        if($this-\u003eafter_delete_user_function != '')\r","            call_user_func($this-\u003eafter_delete_user_function);\r","\r","        // redirect user\r","        $url = $this-\u003eget_uri_path() . \"_success=3\u0026\" . $this-\u003eget_qs();\r","        $this-\u003eredirect($url, $flag);\r","\r","    }\r","\r","\r","    function index($error = ''){\r","\r","        // purpose: called from contoller to display update() data\r","\r","        echo $this-\u003egrid($error);\r","\r","    }\r","\r","    \r","    function sql_delete(){\r","\r","        // purpose: delete the requested record\r","        // returns: false on error, true on success\r","        \r","        $identity_id = $this-\u003ecast_id($_POST[$this-\u003eidentity_name]);\r","\r","        if($identity_id == 0){\r","            $this-\u003edisplay_error(\"missing identity_value\", 'delete()');\r","            return false;\r","        }\r","\r","        if(!$this-\u003eupload_delete($this-\u003etable, $this-\u003eidentity_name, $identity_id, '*', $this-\u003eform_input_control))\r","            return false;\r","\r","        $sql_param = array(':identity_id' =\u003e $identity_id);\r","        $sql = \"delete from `$this-\u003etable` where `$this-\u003eidentity_name` = :identity_id limit 1\";\r","        if($this-\u003equery($sql, $sql_param, 'delete()') === false)\r","            return false;\r","\r","    }\r","\r","\r","    function sql_insert(){\r","\r","        // purpose: generate insert sql statement from the data posted and table's meta data\r","        // returns: false on error, id returned on success\r","\r","        $columns = $this-\u003eget_columns();\r","\r","        if(mb_strlen($this-\u003etable) == 0 || count($columns) == 0){\r","            $this-\u003edisplay_error(\"missing tablename, or get_columns() failed\", 'insert()');\r","            return false;\r","        }\r","\r","        // format list of fields from posted data\r","        $sql_fields = '';\r","        foreach($_POST as $key =\u003e $val){\r","\r","            // don't allow updates on certain fields\r","            if(array_key_exists($key, $this-\u003eexclude_field))\r","                continue;\r","\r","            // checkboxes require a special hidden field to identify unchecked values\r","            if(mb_substr($key, -9) == '-checkbox')\r","                if(mb_substr($key, 0, -9) != $prev_key)\r","                    $key = mb_substr($key, 0, -9);\r","\r","            // same as above but for -selectmultiple\r","            if(mb_substr($key, -15) == '-selectmultiple')\r","                if(mb_substr($key, 0, -15) != $prev_key)\r","                    $key = mb_substr($key, 0, -15);\r","\r","            $prev_key = $key;\r","\r","            if(!(array_search($key, $columns) === false))\r","                $sql_fields .= \"`$key`, \";  \r","        }\r","        $sql_fields = rtrim($sql_fields, ', ');\r","        \r","\r","        // format list of values from posted data\r","        $sql_param = array();\r","        $sql_values = '';\r","        foreach($_POST as $key =\u003e $val){\r","\r","            // don't allow updates on certain fields\r","            if(array_key_exists($key, $this-\u003eexclude_field))\r","                continue;\r","\r","            // checkboxes require a special hidden field to identify unchecked values\r","            if(mb_substr($key, -9) == '-checkbox')\r","                if(mb_substr($key, 0, -9) != $prev_key)\r","                    $key = mb_substr($key, 0, -9);\r","\r","            // same as above but for -selectmultiple\r","            if(mb_substr($key, -15) == '-selectmultiple')\r","                if(mb_substr($key, 0, -15) != $prev_key)\r","                    $key = mb_substr($key, 0, -15);\r","\r","            if(!(array_search($key, $columns) === false)){\r","                $safe_np = $this-\u003esafe_np($key);\r","                $sql_values .= \":$safe_np, \";\r","                $sql_param[\":$safe_np\"] = $this-\u003ecast_value($val, $key);\r","            }\r","\r","            $prev_key = $key;\r","\r","        }\r","\r","        $sql_values = rtrim($sql_values, ', '); \r","        \r","        $sql = \"insert into `$this-\u003etable` ($sql_fields) values ($sql_values);\";\r","        $identity_id = $this-\u003equery($sql, $sql_param, 'insert()');\r","        if($identity_id === false)\r","            return false;\r","\r","        if(!$this-\u003eget_upload($columns, $this-\u003etable, $this-\u003eidentity_name, $identity_id))\r","            return false;\r","\r","        return $identity_id;\r","    }\r","\r","\r","    function sql_update(){\r","\r","        // purpose: generate and run update sql statement from the data posted and table's meta data\r","        // returns: false on error, true on success\r","\r","        $columns = $this-\u003eget_columns();\r","        $identity_id = $this-\u003ecast_id($_POST[$this-\u003eidentity_name]);\r","\r","        if(mb_strlen($this-\u003etable) == 0 || $identity_id == 0 || count($columns) == 0){\r","            $this-\u003edisplay_error(\"missing tablename, or missing identity_value, or get_columns() failed\", 'sql_update()');\r","            return false;\r","        }\r","\r","        // posted values are saved here for pdo execute\r","        $sql_param = array();\r","        $sql_param[':identity_id'] = $identity_id;\r","\r","        // make sql statement from key and values in $_POST data\r","        $sql_set = '';\r","        foreach($_POST as $key =\u003e $val){\r","\r","            // don't allow updates on certain fields\r","            if(array_key_exists($key, $this-\u003eexclude_field))\r","                continue;\r","\r","            // checkboxes require a special hidden field so unchecked values are detectable\r","            if(mb_substr($key, -9) == '-checkbox')\r","                if(!array_key_exists(mb_substr($key, 0, -9), $_POST)) // add key if none exists already\r","                    $key = mb_substr($key, 0, -9);\r","\r","            // same as above, but for selectmultiple \r","            if(mb_substr($key, -15) == '-selectmultiple')\r","                if(!array_key_exists(mb_substr($key, 0, -15), $_POST))\r","                    $key = mb_substr($key, 0, -15);\r","            \r","            if(!(array_search($key, $columns) === false)){\r","                $safe_np = $this-\u003esafe_np($key);\r","                $sql_set .= \"`$key` = :$safe_np, \"; \r","                $sql_param[\":$safe_np\"] = $this-\u003ecast_value($val, $key);\r","            }\r","\r","        }\r","        $sql_set = rtrim($sql_set, ', ');\r","\r","        // run sql update\r","        if($sql_set != ''){\r","\r","            $sql_final = \"update `$this-\u003etable` set $sql_set where `$this-\u003eidentity_name` = :identity_id;\";\r","            \r","            if($this-\u003equery($sql_final, $sql_param, 'update()') === false)\r","                return false;\r","        }\r","\r","        if(!$this-\u003eget_upload($columns, $this-\u003etable, $this-\u003eidentity_name, $identity_id))\r","            return false;\r","\r","        return $identity_id;\r","\r","    }\r","\r","\r","    function sql_update_grid(){\r","\r","        // purpose: generate multiple update sql statements from editable fields in grid()\r","        // returns: false on error, true on success\r","\r","        $columns = $this-\u003eget_columns('grid');\r","        $skip_update_on_column_name = '';\r","\r","        $table = $this-\u003etable;\r","        $identity_name = $this-\u003eidentity_name;\r","        $input_control = $this-\u003egrid_input_control;\r","\r","        if(mb_strlen($table) == 0 || count($columns) == 0 || (count($input_control) == 0 \u0026\u0026 $this-\u003egrid_multi_delete == false)){\r","            $this-\u003edisplay_error(\"missing table name, or get_columns(), or grid_input_control is empty\", 'update_grid()');\r","            return false;\r","        }\r","\r","        // optimization\r","        $run_upload = false;\r","        foreach($input_control as $column_name =\u003e $ctrl)\r","            if($this-\u003eis_upload($input_control, $column_name))\r","                $run_upload = true;\r","\r","        // gather all identity ids from suffix of input_name-identity_id\r","        $arr_identity_id = array();\r","        $prev_identity_id = 0;\r","        $post = array_merge($_POST, $_FILES);\r","        foreach($post as $key =\u003e $val){\r","            \r","            if(!mb_strstr($key, '-'))\r","                continue;    \r","            \r","            $identity_id = $this-\u003ecast_id(mb_substr($key, mb_strrpos($key, '-') + 1));\r","\r","            if($identity_id == 0)\r","                continue;\r","\r","            if($identity_id != $prev_identity_id)\r","                array_push($arr_identity_id, $identity_id);\r","\r","            $prev_identity_id = $identity_id;\r","        }\r","\r","        // run updates\r","        $sql_final = '';\r","        $sql_param = array();\r","        $this-\u003edbh-\u003ebeginTransaction();\r","        foreach($arr_identity_id as $identity_id){\r","\r","            $sql_set = '';\r","            $sql_param[':identity_id'] = $identity_id;\r","\r","            // loop thur editable columns\r","            foreach($input_control as $column_name =\u003e $control){\r","\r","                if(array_search($column_name, $columns) === false)\r","                    continue;\r","\r","                if($column_name == $skip_update_on_column_name)\r","                    continue;\r","\r","                if($this-\u003eis_upload($input_control, $column_name))\r","                    continue;\r","\r","                $safe_np = $this-\u003esafe_np($column_name);\r","                $sql_set .= \"`$column_name` = :$safe_np, \";\r","                $sql_param[\":$safe_np\"] = $this-\u003ecast_value($_POST[\"$column_name-$identity_id\"] ?? '', $column_name, 'grid');\r","\r","            }\r","\r","            // append statements\r","            if(mb_strlen($sql_set) \u003e 0){\r","                \r","                $sql_set = rtrim($sql_set, ', ');\r","                $sql_final = \"update `$table` set $sql_set where `$identity_name` = :identity_id;\\n\";\r","\r","                if($this-\u003equery($sql_final, $sql_param, 'sql_update_grid()') === false)\r","                    return false;\r","                $sql_param = array();\r","            \r","            }\r","\r","        }\r","        $this-\u003edbh-\u003ecommit();\r","\r","        // upload files\r","        if($run_upload)\r","            foreach($arr_identity_id as $identity_id)\r","                $this-\u003eget_upload($columns, $table, $identity_name, $identity_id, 'grid');\r","\r","        // get records to delete\r","        $arr_delete = $_POST['_delete'] ?? array();\r","        if(!is_array($arr_delete))\r","            $arr_delete = array();\r","\r","        // delete records\r","        $sql = '';\r","        $sql_param = array();\r","        foreach($arr_delete as $identity_id){\r","\r","            if($run_upload)\r","                $this-\u003eupload_delete($table, $identity_name, $identity_id, '*', $input_control);\r","\r","            $sql = \"delete from `$table` where `$identity_name` = :identity_id;\";\r","            $sql_param = array(':identity_id' =\u003e $identity_id);\r","            if($this-\u003equery($sql, $sql_param, 'sql_update_grid() - delete') === false)\r","                return false;\r","\r","        }\r","\r","        return true;\r","\r","    }\r","\r","    \r","    function form($error = ''){\r","\r","        // purpose: generate a form to edit or add a record\r","        // if a record is found the form will be populated for editing, otherwise the form is empty and form is for adding/inserting data\r","        // $error = error message to display before form, often from server-side validation\r","        // returns: html\r","\r","        if(mb_strlen($this-\u003eidentity_name) == 0)\r","            return $this-\u003edisplay_error(\"property: identity_name must be set\", 'form()');\r","\r","        if(mb_strlen($this-\u003eform_sql) == 0 \u0026\u0026 mb_strlen($this-\u003etable) == 0)\r","            return $this-\u003edisplay_error(\"property: form_sql or table must be set\", 'form()');\r","\r","        $identity_id = $this-\u003ecast_id($_GET[$this-\u003eidentity_name] ?? $_POST[$this-\u003eidentity_name] ?? 0);\r","\r","        $sql = $this-\u003eform_sql;\r","        $sql_param = $this-\u003eform_sql_param;\r","        \r","        // make sql statement from table name if no sql was provided\r","        if(mb_strlen($sql) == 0){\r","            $sql_param = array(':identity_id' =\u003e $identity_id);\r","            $sql = \"select * from `$this-\u003etable` where `$this-\u003eidentity_name` = :identity_id\";\r","        }\r","\r","        // run query\r","        $result = $this-\u003equery($sql, $sql_param, 'form()');\r","\r","        // quit on error\r","        if($result === false)\r","            return;\r","\r","        $columns = $this-\u003eget_columns('form');\r","        $count = count($result);\r","        $_posted = intval($_POST['_posted'] ?? 0);\r","\r","        // success messages \r","        $success = intval($_GET['_success'] ?? 0);\r","        if($success == 1)\r","            $success = $this-\u003eform_text_record_added;\r","        elseif($success == 2)\r","            $success = $this-\u003eform_text_record_saved; \r","        else\r","            $success = '';\r","\r","        // are we adding (blank form) or editing (populated form) a record\r","        if($count == 0){\r","            $action = 'add';\r","            $title = $this-\u003eform_text_title_add;\r","            $validate = $this-\u003eon_insert_validate;\r","        }\r","        else{\r","            $action = 'edit';\r","            $title = $this-\u003eform_text_title_edit;\r","            $validate = $this-\u003eon_update_validate;\r","        }\r","\r","        // get 1 row of data if available\r","        $row = false;\r","        $identity_id = 0; // id fetched below\r","        if(count($result) \u003e 0){\r","            $row = $result[0];\r","            $identity_id = $this-\u003ecast_id($row[$this-\u003eidentity_name]);\r","        }\r","\r","        if($action == 'edit' \u0026\u0026 $identity_id == 0)\r","            $error .= \"Missing identity_id. If using a custom form_sql statement be sure to include the identity. \";\r","    \r","        // query string is used here in form() to maintain pagination and sort data so user can return back to the same place in grid results \r","        $qs = $this-\u003eget_qs();\r","        if(mb_strlen($qs) \u003e 0)\r","            $qs = \"$qs\";\r","        \r","        $uri_path = $this-\u003eget_uri_path();\r","\r","        $html  = \"\u003cdiv id='lm' class='lm_form_wrapper'\u003e\\n\";\r","        $html .= \"\u003cform action='$uri_path$qs' method='post' enctype='multipart/form-data'\u003e\\n\";\r","        $html .= \"\u003cinput type='hidden' name='_csrf' value='{$_SESSION['_csrf']}'\u003e\\n\";\r","        $html .= \"\u003cinput type='hidden' name='_posted' value='1'\u003e\\n\";\r","\r","        if(mb_strlen($error) \u003e 0)\r","            $html .= \"\u003cdiv class='lm_error'\u003e\u003cb\u003e$error\u003c/b\u003e\u003c/div\u003e\\n\";\r","        \r","        if(mb_strlen($success) \u003e 0)\r","            $html .= \"\u003cdiv class='lm_success'\u003e\u003cb\u003e$success\u003c/b\u003e\u003c/div\u003e\\n\";\r","        \r","        $html .= \"\u003ctable cellpadding='2' cellspacing='1' border='0' class='lm_form'\u003e\\n\";\r","\r","        if(mb_strlen($title) \u003e 0)\r","            $html .= \"\u003ctr\u003e\\n    \u003cth colspan='2'\u003e$title\u003c/th\u003e\\n\u003c/tr\u003e\\n\";\r","\r","        // loop thru fields\r","        foreach($columns as $column_name){\r","\r","            if($column_name == $this-\u003eidentity_name \u0026\u0026 ($this-\u003eform_display_identity == false || $action == 'add'))\r","                continue;\r","\r","            // get data from database or repost\r","            if($_posted == 1 \u0026\u0026 ($this-\u003eform_input_control[$column_name]['type'] ?? '') != 'readonly')\r","                $value = $_POST[$column_name] ?? '';\r","            elseif($count == 0)\r","                $value = $this-\u003eform_default_value[$column_name] ?? '';\r","            else\r","                $value = $row[$column_name];\r","\r","            // field label\r","            $title = $this-\u003eformat_title($column_name, $this-\u003erename[$column_name] ?? '');\r","\r","            // render the html control according to the type of data\r","            $control = \"\";    \r","\r","            if($column_name == $this-\u003eidentity_name)\r","                $control = $this-\u003eclean_out($value);\r","            elseif(array_key_exists($column_name, $this-\u003eform_input_control))\r","                $control = $this-\u003eget_input_control($column_name, $value, $this-\u003eform_input_control[$column_name], 'form', $validate);\r","            else\r","                $control = $this-\u003eget_input_control($column_name, $value, null, 'form', $validate);\r","        \r","            $html .= \"\u003ctr\u003e\\n\";\r","            $html .= \"    \u003ctd\u003e$title:\u003c/td\u003e\\n\";\r","            $html .= \"    \u003ctd\u003e$control\u003c/td\u003e\\n\";\r","            $html .= \"\u003c/tr\u003e\\n\";\r","        }\r","\r","        $html .= \"\u003c/table\u003e\\n\";\r","\r","        if($action == 'edit')\r","            $html .= \"\u003cinput type='hidden' name='$this-\u003eidentity_name' value='$identity_id'\u003e\\n\";\r","\r","        // action \r","        if($action == 'edit')\r","            $html .= \"\u003cinput type='hidden' name='action' value='update'\u003e\\n\";\r","        else\r","            $html .= \"\u003cinput type='hidden' name='action' value='insert'\u003e\\n\";\r","        \r","        // add buttons\r","        if($action == 'edit')\r","            $html .= \"\u003cdiv class='lm_form_button_bar'\u003e$this-\u003eform_back_button $this-\u003eform_delete_button $this-\u003eform_update_button\u003c/div\u003e\";\r","        else\r","            $html .= \"\u003cdiv class='lm_form_button_bar'\u003e$this-\u003eform_back_button $this-\u003eform_add_button\u003c/div\u003e\";\r","\r","        $html .= $this-\u003eform_additional_html;\r","        $html .= \"\u003c/form\u003e\\n\";\r","        $html .= \"\u003c/div\u003e\u003c!-- close #lm --\u003e\\n\";\r","        $html .= $this-\u003edelete_js($identity_id, 'form');\r","        \r","        return $html;    \r","\r","    }\r","\r","    \r","    function grid($error = ''){\r","\r","        // purpose: function to list a table of records. aka data grid\r","        // returns: html\r","        // populate_from_post tells inputs to populate from $_POST instead of the database. useful to preserve data when displaying validation errors.\r","        // in grid_sql, select the identity_id as the last column to display the edit and delete links\r","        // example: $lm-\u003egrid_sql = 'select title, create_date, foo_id from foo';\r","\r","        if(mb_strlen($this-\u003eidentity_name) == 0 || (mb_strlen($this-\u003egrid_sql) == 0 \u0026\u0026 mb_strlen($this-\u003etable) == 0)){\r","            $this-\u003edisplay_error(\"missing grid_sql and table (one is required), or missing identity_name\", 'form()');\r","            return;\r","        }\r","\r","        // local copies \r","        $sql = trim($this-\u003egrid_sql);\r","        $sql_param = $this-\u003egrid_sql_param;\r","        $grid_limit = intval($this-\u003egrid_limit);\r","        $uri_path = $this-\u003eget_uri_path();\r","        $default_order_by = $this-\u003egrid_default_order_by;\r","\r","        if($default_order_by == '')\r","            $default_order_by = \"`$this-\u003eidentity_name`\";\r","\r","        // remove line feeds which can cause problems with parsing\r","        $sql = preg_replace('/[\\n\\r]/', ' ', $sql);\r","\r","        // default queries if only table and id names were provided\r","        if(mb_strlen($sql) == 0)\r","            $sql = \"select *, `$this-\u003eidentity_name` from `$this-\u003etable` order by $default_order_by\";\r","\r","        // inject funciton for counting\r","        $sql = preg_replace('/^select/i', 'select sql_calc_found_rows', $sql);\r","\r","        // get input\r","        $_posted = intval($_REQUEST['_posted'] ?? 0);\r","        $_search = $this-\u003eclean_out($_REQUEST['_search'] ?? '');\r","        $_pagination_off = intval($_REQUEST['_pagination_off'] ?? 0);\r","        $_order_by = abs(intval($_REQUEST['_order_by'] ?? 0)); // order by is numeric index to column\r","        $_desc = abs(intval($_REQUEST['_desc'] ?? 0));         // descending order flag\r","        $_offset = abs(intval($_REQUEST['_offset'] ?? 0));     // pagination offset\r","        $_export = intval($_REQUEST['_export'] ?? 0); \r","        \r","        $qs = $this-\u003eget_qs();\r","\r","        // header links - invert current sort\r","        $_desc_invert = 1;\r","        if($_desc == 1)\r","            $_desc_invert = 0;\r","\r","        // success messages \r","        $success = intval($_GET['_success'] ?? 0);\r","        if($success == 1)\r","            $success = $this-\u003egrid_text_record_added;\r","        elseif($success == 2)\r","            $success = $this-\u003egrid_text_changes_saved;\r","        elseif($success == 3)\r","            $success = $this-\u003egrid_text_record_deleted;\r","        else\r","            $success = '';\r","\r","        // column array and column count \r","        $columns = $this-\u003eget_columns('grid');\r","        if(!$columns)\r","            return;\r","        $column_count = count($columns);\r","\r","        // alter order\r","        $desc_str = '';\r","        if($_order_by \u003e 0){\r","\r","            if($_desc == 1)\r","                $desc_str = 'desc'; \r","\r","            $sql = rtrim($sql, '; '); // remove last semicolon\r","            \r","            // try to remove last 'order by'. we need to allow functions in order by and order by in subqueries\r","            $this-\u003emb_preg_match_all('/order\\s+by\\s/im', $sql, $matches, PREG_OFFSET_CAPTURE);\r","            if(count($matches) \u003e 0){\r","                $match = end($matches[0]);\r","                $sql = mb_substr($sql, 0, $match[1]);\r","            }\r","\r","            $sql .= \" order by $_order_by $desc_str\"; // add requested sort order\r","        }\r","\r","        // remove existing limit\r","        $sql = preg_replace('/\\s+limit\\s+[0-9,\\s]+$/i', '', $sql); \r","\r","        // add limit and offset for pagination\r","        if($_pagination_off == 0 \u0026\u0026 $_export == 0 \u0026\u0026 $grid_limit \u003e 0)\r","            $sql .= \" limit $_offset, $grid_limit\"; \r","\r","        // run query\r","        $result = $this-\u003equery($sql, $sql_param, 'grid() run query');\r","        if(!is_array($result))\r","            $result = array();\r","\r","        // get count\r","        $count = 0;\r","        $sql = 'select found_rows() as cnt';\r","        $result_count = $this-\u003equery($sql);\r","        foreach($result_count as $row)\r","            $count = $row['cnt'];\r","\r","        // export data to CSV and quit \r","        if($_export == 1 \u0026\u0026 $count \u003e 0){\r","            $this-\u003eexport($result, $columns);\r","            return;    \r","        }\r","\r","        // populate link placeholders    \r","        $grid_add_link = $this-\u003egrid_add_link;\r","        $grid_edit_link = $this-\u003egrid_edit_link;\r","        $grid_delete_link = $this-\u003egrid_delete_link;\r","        $grid_export_link = $this-\u003egrid_export_link;\r","        $grid_add_link = str_replace('[script_name]', $uri_path, $grid_add_link);\r","        $grid_add_link = str_replace('[qs]', $qs, $grid_add_link);\r","        $grid_edit_link = str_replace('[script_name]', $uri_path, $grid_edit_link);\r","        $grid_edit_link = str_replace('[qs]', $qs, $grid_edit_link);\r","        $grid_edit_link = str_replace('[identity_name]', $this-\u003eidentity_name, $grid_edit_link);\r","        $grid_delete_link = str_replace('[script_name]', $uri_path, $grid_delete_link);\r","        $grid_delete_link = str_replace('[qs]', $qs, $grid_delete_link);\r","        $grid_delete_link = str_replace('[identity_name]', $this-\u003eidentity_name, $grid_delete_link);\r","        $grid_export_link = str_replace('[script_name]', $uri_path, $grid_export_link);\r","        $grid_export_link = str_replace('[qs]', $qs, $grid_export_link);\r","        $links = $grid_edit_link . ' ' . $grid_delete_link;\r","\r","        // pagination and save changes link bar\r","        $pagination = $this-\u003eget_pagination($count, $grid_limit, $_offset, $_pagination_off);\r","        $button = '';\r","        if(count($this-\u003egrid_input_control) \u003e 0 || $this-\u003egrid_multi_delete == true)\r","            $button = \"\u003cinput type='submit' name='__update_grid' value='$this-\u003egrid_text_save_changes' class='lm_button lm_save_changes_button'\u003e\";\r","        $pagination_button_bar = \"\u003ctable cellpadding='2' cellspacing='1' border='0' width='100%' class='lm_pagination'\u003e\u003ctr\u003e\u003ctd style='text-align: left'\u003e$pagination\u003c/td\u003e\u003ctd style='text-align: right'\u003e$button\u003c/td\u003e\u003c/tr\u003e\u003c/table\u003e\\n\";\r","\r","        // search bar\r","        $search_box = '';\r","        if($this-\u003egrid_show_search_box){\r","    \r","            // carry values defined in query_string_list\r","            $query_string_list_inputs = '';\r","            if(mb_strlen($this-\u003equery_string_list) \u003e 0){\r","                $arr = explode(',', trim($this-\u003equery_string_list, ', '));\r","                foreach($arr as $val)\r","                    $query_string_list_inputs .= \"\u003cinput type='hidden' name='$val' value='\" . $this-\u003eclean_out($_REQUEST[$val] ?? '') . \"'\u003e\";\r","            }\r","            \r","            $search_box = $this-\u003egrid_search_box;\r","            $search_box = str_replace('[script_name]', $uri_path . $this-\u003eget_qs('') , $search_box); // for 'x' cancel do add get_qs('') to carry query_string_list\r","            $search_box = str_replace('[_search]', $_search, $search_box);\r","            $search_box = str_replace('[_csrf]', $_SESSION['_csrf'], $search_box);\r","            $search_box = str_replace('[query_string_list]', $query_string_list_inputs, $search_box);\r","        }\r","\r","        $add_record_search_bar = \"\u003ctable cellpadding='2' cellspacing='1' border='0' width='100%' class='lm_add_search'\u003e\u003ctr\u003e\u003ctd style='text-align: left'\u003e$grid_add_link \u0026nbsp; $grid_export_link\u003c/td\u003e\u003ctd style='text-align: right'\u003e$search_box\u003c/td\u003e\u003c/tr\u003e\u003c/table\u003e\\n\";\r","\r","        // generate table header\r","        $head = \"\u003ctr\u003e\\n\";\r","        if($this-\u003egrid_multi_delete)\r","            $head .= \"\u003cth\u003e\u003ca href='#' onclick='return _toggle();' title='toggle checkboxes'\u003e$this-\u003egrid_text_delete\u003c/a\u003e\u003c/th\u003e\\n\";\r","        \r","        $i = 0;\r","        foreach($columns as $column_name){\r","\r","            $title = $this-\u003eformat_title($column_name, $this-\u003erename[$column_name] ?? '');\r","\r","            if($column_name == $this-\u003eidentity_name \u0026\u0026 $i == ($column_count - 1))\r","                $head .= \"    \u003cth\u003e\u003c/th\u003e\\n\"; // if identity is last column then this is the column with the edit and delete links\r","            else\r","                $head .= \"    \u003cth\u003e\u003ca href='{$uri_path}_order_by=\" . ($i + 1) . \"\u0026_desc=$_desc_invert\u0026\" . $this-\u003eget_qs('_search') . \"'\u003e$title\u003c/a\u003e\u003c/th\u003e\\n\";\r","        \r","            $i++;\r","\r","        }\r","        $head .= \"\u003c/tr\u003e\\n\";\r","            \r","        // start generating output //\r","        $html = \"\u003cdiv id='lm'\u003e\\n\";\r","\r","        if(mb_strlen($success) \u003e 0)\r","            $html .= \"\u003cdiv class='lm_success'\u003e\u003cb\u003e$success\u003c/b\u003e\u003c/div\u003e\\n\";\r","        if(mb_strlen($error) \u003e 0)\r","            $html .= \"\u003cdiv class='lm_error'\u003e\u003cb\u003e$error\u003c/b\u003e\u003c/div\u003e\\n\";\r","        \r","        $html .= $add_record_search_bar;\r","\r","        $html .= \"\u003cform action='$uri_path$qs' method='post' onsubmit='return _update_grid()' enctype='multipart/form-data'\u003e\\n\";\r","        $html .= \"\u003cinput type='hidden' name='_posted' value='1'\u003e\\n\";\r","        $html .= \"\u003cinput type='hidden' name='_csrf' value='{$_SESSION['_csrf']}'\u003e\\n\";\r","\r","        // quit if there's no data\r","        if($count \u003c= 0){\r","            $html .= \"\u003cdiv class='lm_error'\u003e\u003cb\u003e$this-\u003egrid_text_no_records_found\u003c/b\u003e\u003c/div\u003e\u003c/form\u003e\u003c/div\u003e\u003c!-- close #lm --\u003e\\n\";\r","            return $html;    \r","        }    \r","\r","        // buttons \u0026 pagination on top. only show if we have a lot of records\r","        if($count \u003e 30)\r","            $html .= $pagination_button_bar;\r","\r","        $html .= \"\u003ctable cellpadding='2' cellspacing='1' border='0' width='100%' class='lm_grid'\u003e\\n\";\r","        $html .= $head;\r","\r","        // print rows\r","        $j = 0;\r","        foreach($result as $row){\r","\r","            // highlight last updated or inserted row\r","            $shaded = '';\r","            if(($_GET[$this-\u003eidentity_name] ?? '') == ($row[$this-\u003eidentity_name] ?? '') \u0026\u0026 mb_strlen($_GET[$this-\u003eidentity_name] ?? '') \u003e 0)\r","                $shaded = \"class='lm_active'\";\r","\r","            // print a row\r","            $html .= \"\u003ctr $shaded\u003e\\n\";\r","\r","            // delete selection checkbox\r","            if($this-\u003egrid_multi_delete){\r","                $html .= \"\u003ctd align='center'\u003e\u003clabel\u003e\u003cinput type='checkbox' name='_delete[]' value='{$row[$this-\u003eidentity_name]}'\u003e\u003c/label\u003e\u003c/td\u003e\\n\";\r","            }\r","\r","            // print columns\r","            $i = 0;\r","            foreach($columns as $column_name){\r","\r","                $value = $row[$column_name];\r","\r","                // edit \u0026 delete links\r","                if($column_name == $this-\u003eidentity_name \u0026\u0026 $i == ($column_count - 1))\r","                    $html .= \"    \u003ctd nowrap\u003e\" . str_replace('[identity_id]', $value, $links) . \"\u003c/td\u003e\\n\";\r","\r","                // input fields\r","                elseif(array_key_exists($column_name, $this-\u003egrid_input_control)){\r","                    if(mb_strlen($error) \u003e 0 \u0026\u0026 $_posted == 1) // repopulate from previous post when validation error is displayed\r","                        $value = $_POST[$column_name . '-' . $row[$this-\u003eidentity_name]] ?? '';\r","                    $html .= '    \u003ctd\u003e' . $this-\u003eget_input_control($column_name . '-' . $row[$this-\u003eidentity_name], $value,  $this-\u003egrid_input_control[$column_name], 'grid') . \"\u003c/td\u003e\\n\";\r","                }\r","\r","                // output\r","                elseif(array_key_exists($column_name, $this-\u003egrid_output_control))\r","                    $html .= '    \u003ctd\u003e' . $this-\u003eget_output_control($column_name . '-' . $row[$this-\u003eidentity_name], $value, $this-\u003egrid_output_control[$column_name], 'grid') . \"\u003c/td\u003e\\n\";\r","\r","                // anything else\r","                else\r","                    $html .= '    \u003ctd\u003e' . $this-\u003eget_output_control($column_name . '-' . $row[$this-\u003eidentity_name], $value, null, 'grid') . \"\u003c/td\u003e\\n\";\r","\r","                $i++; // column index\r","            }\r","\r","            $html .= \"\u003c/tr\u003e\\n\";\r","\r","            // repeat header\r","            if($this-\u003egrid_repeat_header_at \u003e 0)\r","                if($j % $this-\u003egrid_repeat_header_at == 0 \u0026\u0026 $j \u003c $count \u0026\u0026 $j \u003e 0)\r","                    $html .= $head;\r","                \r","            // row counter    \r","            $j++;\r","        }\r","\r","        $html .= \"\u003c/table\u003e\\n\";\r","\r","        // buttons \u0026 pagination, close form\r","        $html .= $pagination_button_bar;\r","        $html .= \"\u003c/form\u003e\\n\";\r","        $html .= \"\u003c/div\u003e\u003c!-- close #lm --\u003e\\n\";\r","        $html .= $this-\u003edelete_js(0, 'grid');\r","\r","        return $html;\r","\r","    }\r","\r","    \r","    function delete_js($identity_id = 0, $_called_from = ''){\r","\r","        // purpose: extra form \u0026 js for deleing records and going back\r","        // returns: html\r","\r","        $uri_path = $this-\u003eget_uri_path();\r","        $qs = $this-\u003eget_qs(); \r","        $back_link = $uri_path . $qs;\r","\r","        // append id for row highlighting\r","        if($identity_id \u003e 0)\r","            $back_link .= \"\u0026$this-\u003eidentity_name=$identity_id\";\r","\r","        // escape for js\r","        $delete_confirm = str_replace(\"'\", \"\\'\", $this-\u003edelete_confirm);\r","        $update_grid_confirm = str_replace(\"'\", \"\\'\", $this-\u003eupdate_grid_confirm);\r","\r","        return \"\r","        \u003cform action='$uri_path$qs' method='post' name='delete_js'\u003e\r","        \u003cinput type='hidden' name='action' value='delete' \u003e\r","        \u003cinput type='hidden' name='$this-\u003eidentity_name' value='$identity_id' \u003e\r","        \u003cinput type='hidden' name='_csrf' value='{$_SESSION['_csrf']}' \u003e\r","        \u003cinput type='hidden' name='_called_from' value='$_called_from' \u003e\r","        \u003c/form\u003e\r","\r","        \u003cscript type='text/javascript'\u003e\r","        \r","        function _delete(id){\r","\r","            if(!confirm('$delete_confirm'))\r","                return false;\r","\r","            if(id)\r","                document.delete_js.elements['$this-\u003eidentity_name'].value = id;\r","            \r","            document.delete_js.submit();\r","            return false;\r","\r","        }    \r","\r","        function _back(){\r","\r","            window.location.href = '$back_link';\r","\r","        }    \r","\r","        function _toggle(){\r","        \r","            var form_cnt = document.forms.length;\r","            var i;\r","\r","            for (i = 0; i \u003c form_cnt; i++)\r","                for (j = 0; j \u003c document.forms[i].length; j++)\r","                    if(document.forms[i].elements[j].name == '_delete[]')\r","                        document.forms[i].elements[j].checked = !document.forms[i].elements[j].checked;\r","\r","            return false;\r","\r","        }\r","\r","        function _update_grid(){\r","\r","            var form_cnt = document.forms.length;\r","            var i;\r","            var delete_cnt = 0;\r","            var msg = '$update_grid_confirm';\r","\r","            for (i = 0; i \u003c form_cnt; i++)\r","                for (j = 0; j \u003c document.forms[i].length; j++)\r","                    if(document.forms[i].elements[j].name == '_delete[]')\r","                        if(document.forms[i].elements[j].checked)\r","                            delete_cnt++;\r","\r","            if(delete_cnt == 0)\r","                return true;\r","\r","            msg = msg.replace('[count]', delete_cnt);\r","            if(!confirm(msg))\r","                return false;\r","\r","            return true;\r","\r","        }\r","\r","        \u003c/script\u003e\r","        \";\r","    }\r","    \r","\r","    function html_image_input($field_name, $file_name){\r","\r","        // purpose: if image exists, display image and delete checkbox. also display file input\r","        // returns: html\r","\r","        $html = '';\r","        $class = $this-\u003eget_class_name($field_name);\r","\r","        if(isset($file_name) \u0026\u0026 mb_strlen($file_name) \u003e 0){\r","        \r","            if(mb_strlen($this-\u003ethumb_path))\r","                $html .= \"\u003ca href='$this-\u003eupload_path/$file_name' target='_blank'\u003e\u003cimg src='$this-\u003ethumb_path/$file_name' alt='' $this-\u003eimage_style \u003e\u003c/a\u003e\";\r","            else\r","                $html .= \"\u003ca href='$this-\u003eupload_path/$file_name' target='_blank'\u003e\u003cimg src='$this-\u003eupload_path/$file_name' alt='' $this-\u003eimage_style \u003e\u003c/a\u003e\";\r","\r","            $html .= \" \u003clabel\u003e\u003cinput type='checkbox' name='{$field_name}-delete' value='1' \u003e$this-\u003etext_delete_image\u003c/label\u003e\u003cbr\u003e\";\r","        }\r","\r","        $html .= \"\u003cinput type='file' name='$field_name' class='$class' size='$this-\u003eform_text_input_size'\u003e\";\r","\r","        return $html;\r","\r","    }\r","\r","\r","    function html_document_input($field_name, $file_name){\r","\r","        // purpose: if document exists, display link and delete checkbox. also display file input\r","        // returns: html\r","\r","        $html = '';\r","        $class = $this-\u003eget_class_name($field_name);\r","\r","        if(mb_strlen($file_name ?? '') \u003e 0)\r","            $html .= \"\u003ca href='$this-\u003eupload_path/$file_name' target='_blank'\u003e$file_name\u003c/a\u003e \u003clabel\u003e\u003cinput type='checkbox' name='{$field_name}-delete' value='1'\u003e$this-\u003etext_delete_document\u003c/label\u003e\u003cbr \u003e\";\r","\r","        $html .= \"\u003cinput type='file' name='$field_name' class='$class' size='$this-\u003eform_text_input_size'\u003e\";\r","\r","        return $html;\r","\r","    }\r","\r","\r","    function html_image_output($file_name){\r","\r","        // purpose: if image exists, display image depending on settings and if thumbnail exists\r","        // returns: html\r","\r","        if(!isset($file_name) || mb_strlen($file_name) == 0)\r","            return;\r","\r","        if($this-\u003egrid_show_images == false)\r","            return \"\u003ca href='$this-\u003eupload_path/$file_name' target='_blank'\u003e\" . $this-\u003eclean_out($file_name, $this-\u003egrid_ellipse_at) . \"\u003c/a\u003e\";\r","        elseif(mb_strlen($this-\u003ethumb_path))\r","            return \"\u003ca href='$this-\u003eupload_path/$file_name' target='_blank'\u003e\u003cimg src='$this-\u003ethumb_path/$file_name' alt='' $this-\u003eimage_style \u003e\u003c/a\u003e\";\r","        else\r","            return \"\u003ca href='$this-\u003eupload_path/$file_name' target='_blank'\u003e\u003cimg src='$this-\u003eupload_path/$file_name' alt='' $this-\u003eimage_style \u003e\u003c/a\u003e\";\r","\r","\r","    }\r","\r","\r","    function html_document_output($file_name){\r","\r","        // purpose: if exists, display document link\r","        // returns: html\r","\r","        $html = '';\r","        if(mb_strlen($file_name) \u003e 0)\r","            $html = \"\u003ca href='$this-\u003eupload_path/$file_name' target='_blank'\u003e\" . $this-\u003eclean_out($file_name, $this-\u003egrid_ellipse_at) . \"\u003c/a\u003e\";\r","\r","        return $html;\r","\r","    }\r","\r","\r","    function html_html_output($value){\r","\r","        // purpose: when html is displayed in grid remove the tags and just display the plain text content\r","        // returns: html\r","\r","        if(mb_strlen($value) == 0)\r","            return;\r","\r","        $html = strip_tags($value);\r","        $html = str_replace('\u0026nbsp;', ' ', $html);\r","\r","        if($this-\u003egrid_ellipse_at \u003e 0)\r","            if(mb_strlen($html) \u003e $this-\u003egrid_ellipse_at)\r","                $html = mb_substr($html, 0, $this-\u003egrid_ellipse_at) . \"...\";\r","        $html = str_replace('\u003c', '\u0026lt;', $html);\r","        $html = str_replace('\u003e', '\u0026gt;', $html);\r","\r","        return $this-\u003eclean_out($html);\r","\r","    }\r","\r","    \r","    function html_radio($field_name, $value, $sql, $sql_param = array()){    \r","\r","        // purpose: render html radio input, note sql query should return 2 columns\r","        // returns: html\r","\r","        $class = $this-\u003eget_class_name($field_name);\r","\r","        if(!is_array($sql_param))\r","            $sql_param = array();\r","\r","        // if no sql is provided render 1 = yes/ 0 = no\r","        if($sql == '')\r","            $sql = \"select 1 as val, 'Yes' as opt union select 0, 'No'\";\r","\r","        $result = $this-\u003equery_cache($sql, $sql_param, 'html_radio()');\r","\r","        $html = '';    \r","        foreach($result as $row){\r","\r","            $val = current($row);\r","            $opt = next($row);\r","\r","            $checked = \"\";\r","            if($val == $value)\r","                $checked = \"checked='checked'\";\r","            \r","            $html .= \"\u003clabel\u003e\u003cinput type='radio' name='$field_name' class='$class' value='\" . $this-\u003eclean_out($val) . \"' $checked \u003e\" . $this-\u003eclean_out($opt) . \"\u003c/label\u003e \";\r","        }\r","        \r","        return $html;\r","\r","    }\r","\r","\r","    function html_select($field_name, $value, $sql, $sql_param = array(), $js_or_style = '', $first_option_blank = true, $multiple = 0){\r","\r","        // purpose: render html select dropdown from sql query\r","        // returns: html\r","        // sample query: select 0 as val, 'no' as opt union select 1, 'yes'\r","\r","        $html = '';\r","        $class = $this-\u003eget_class_name($field_name);\r","\r","        if(!is_array($sql_param))\r","            $sql_param = array();\r","\r","        // if no sql is provided render 1 = yes, 0 = no\r","        if($sql == '')\r","            $sql = \"select 1 as val, 'Yes' as opt union select 0, 'No'\";\r","\r","        $result = $this-\u003equery_cache($sql, $sql_param, 'html_select()');\r","\r","        if($multiple == 0){\r","\r","            if($first_option_blank)\r","                $html .= \"\u003coption value=''\u003e\u0026nbsp;\u003c/option\u003e\";\r","\r","            foreach($result as $row){\r","\r","                $val = current($row);\r","                $opt = next($row);\r","\r","                $selected = '';\r","                if($val == $value)\r","                    $selected = \"selected='selected'\";\r","\r","                $html .= \"\u003coption value='\" . $this-\u003eclean_out($val) . \"' $selected\u003e\" . $this-\u003eclean_out($opt) . \"\u003c/option\u003e\";\r","            }\r","            $html = \"\u003cselect name='$field_name' class='$class' $js_or_style\u003e$html\u003c/select\u003e\";\r","            return $html;\r","        }\r","            \r","        // render multiple select\r","        $html = \"\";\r","        if($first_option_blank)\r","            $html .= \"\u003coption value=''\u003e\u0026nbsp;\u003c/option\u003e\";\r","\r","        $value  = \"$this-\u003edelim$value$this-\u003edelim\";\r","        foreach($result as $row){\r","\r","            $val = current($row);\r","            $opt = next($row);\r","\r","            $selected = '';    \r","            if(mb_strstr($value, \"$this-\u003edelim$val$this-\u003edelim\"))\r","                $selected = \"selected='selected'\";\r","        \r","            $html .= \"\u003coption value='\" . $this-\u003eclean_out($val) . \"' $selected\u003e\" . $this-\u003eclean_out($opt) . \"\u003c/option\u003e\";\r","        }    \r","\r","        // hidden field at the end assists in detecting no selections\r","        $html = \"\u003cselect name='{$field_name}[]' class='$class' multiple='multiple' size='$multiple' $js_or_style\u003e$html\u003c/select\u003e\u003cinput type='hidden' name='{$field_name}-selectmultiple' value=''\u003e\";\r","        return $html;\r","\r","    }\r","\r","\r","    function html_checkbox($field_name, $value, $sql, $sql_param = array()){\r","\r","        // purpose: render checkbox inputs\r","        // returns: html\r","\r","        $class = $this-\u003eget_class_name($field_name);\r","\r","        if(!is_array($sql_param))\r","            $sql_param = array();\r","\r","        // make hidden field name. an additional hidden field is require to detect presence of checkbox. \r","        $i = mb_strrpos($field_name, '-');\r","        if($i \u003e 0)\r","            $field_name_hidden = mb_substr($field_name, 0, $i) . '-checkbox' . mb_substr($field_name, $i); // grid format field_name-checkbox-identity_id\r","        else\r","            $field_name_hidden = $field_name . '-checkbox';\r","\r","        // if no sql is provided just return a single checkbox for 1 = yes\r","        $checked = '';\r","        if($sql == ''){\r","            \r","            if(intval($value) \u003e 0)\r","                $checked = \"checked='checked'\";\r","            \r","            return \"\u003clabel\u003e\u003cinput type='checkbox' name='$field_name' class='$class' value='1' $checked \u003e\u003c/label\u003e\u003cinput type='hidden' name='$field_name_hidden' value=''\u003e\";\r","        }\r","\r","        $result = $this-\u003equery_cache($sql, $sql_param, 'html_checkbox()');\r","\r","        // make delimited string of previous post\r","        if(is_array($value))\r","            $value = $this-\u003edelim . implode($this-\u003edelim, $value) . $this-\u003edelim;\r","        else\r","            $value = $this-\u003edelim . $value . $this-\u003edelim;\r","\r","        $html = '';\r","        foreach($result as $row){\r","\r","            $val = current($row);\r","            $opt = next($row);\r","\r","            $checked = '';    \r","            if(mb_strstr($value, $this-\u003edelim . $val . $this-\u003edelim))\r","                $checked = \"checked='checked'\";\r","\r","            $html .= \"\u003clabel\u003e\u003cinput type='checkbox' name='{$field_name}[]' class='$class' value='\" . $this-\u003eclean_out($val) . \"' $checked \u003e\" . $this-\u003eclean_out($opt) . \"\u003c/label\u003e\u0026nbsp;\";\r","        }\r","        $html .= \"\u003cinput type='hidden' name='$field_name_hidden' value='0'\u003e\";\r","\r","        return $html;\r","\r","    }\r","\r","   \r","    function cast_value($val, $column_name = '', $posted_from = 'form'){\r","        \r","        // purpose: cast data going into the database. set blanks null and format dates\r","        // returns: string\r","        // $column_name is not used right now but might be needed as a hack to cast by column name for databases like sqlite\r","        // missing types seem to always be numbers\r","\r","        if(is_array($val))\r","            $val = implode($this-\u003edelim, $val);\r","\r","        $val = trim($val);\r","\r","        if($posted_from == 'grid')\r","            $type = $this-\u003egrid_input_control[$column_name]['type'] ?? '';\r","        else\r","            $type = $this-\u003eform_input_control[$column_name]['type'] ?? '';\r","\r","        if(isset($this-\u003ecast_user_function[$column_name]))\r","            $val = call_user_func($this-\u003ecast_user_function[$column_name], $val);\r","        elseif($type == 'date')\r","            $val = $this-\u003edate_in($val);\r","        elseif($type == 'datetime')\r","            $val = $this-\u003edate_in($val, true);\r","        elseif($type == 'number')\r","            $val = $this-\u003enumber_in($val);\r","        \r","        if(!isset($val) || mb_strlen($val) == 0)\r","            $val = null;\r","\r","        return $val;\r","\r","    }\r","\r","\r","    function cast_id($str){\r","\r","        // purpose: similar to intval() but supports mysql bigint and does not overflow\r","\r","        if(isset($str) \u0026\u0026 preg_match('/^-?[0-9]{1,30}$/', $str))\r","            return $str;\r","\r","        return 0;\r","\r","    }\r","\r","    \r","    function clean_file_name($file_name){\r","\r","        // purpose: make uniform file_names to lowercase, no dots, no spaces\r","\r","        $file_name = mb_strtolower($file_name);\r","        $ext = pathinfo($file_name, PATHINFO_EXTENSION);\r","        $prefix = mb_substr($file_name, 0, (mb_strlen($ext) + 1) * -1); \r","        $prefix = str_replace(' ', '_', $prefix);\r","        $prefix = preg_replace('([^0-9a-z_\\-])', '', $prefix);\r","        return \"$prefix.$ext\";\r","\r","    }\r","\r","\r","    function clean_out($str, $ellipse_at = 0){\r","\r","        // purpose: escape html output w/ optional ellipsing\r","\r","        if(!isset($str))\r","            return '';\r","\r","        if(is_array($str))\r","            $str = implode($this-\u003edelim, $str);\r","        elseif($ellipse_at \u003e 0 \u0026\u0026 mb_strlen($str) \u003e $ellipse_at)\r","            $str = mb_substr($str, 0, $ellipse_at, $this-\u003echarset) . \"...\";\r","\r","        // remove illegal characters\r","        $str = mb_convert_encoding($str, $this-\u003echarset, mb_detect_encoding($str));\r","\r","        return htmlspecialchars($str, ENT_QUOTES, $this-\u003echarset);\r","    }\r","\r","\r","    function number_in($str){\r","\r","        // purpose: swap out decimal separator and remove any extra chars going into database\r","        \r","        if($this-\u003edecimal_separator != '.'){\r","            $str = str_replace('.', '', $str);\r","            $str = str_replace($this-\u003edecimal_separator, '.', $str); \r","        }\r","\r","        if(mb_strlen($this-\u003erestricted_numeric_input) == 0)\r","            return $str;\r","\r","        return preg_replace($this-\u003erestricted_numeric_input, '', $str);\r","\r","    }\r","\r","\r","    function date_in($str, $use_time = false){\r","\r","        // purpose: convert local format to database format\r","\r","        if($str == '')\r","            return;\r","\r","        // remove spaces between slash or dash delimiters. allow user to be a little sloppy.\r","        $str = preg_replace('/([0-9]+)\\s?([\\/\\-]){1}\\s?([0-9]+)\\s?([\\/\\-]){1}\\s?([0-9]+)/', '\\1\\2\\3\\4\\5', $str);\r","\r","        // strtotime requires dash delimiter when using d/m/y   \r","        if(preg_match('/[dj].*[mn]/', $this-\u003edate_out))\r","            $str = str_replace('/', '-', $str);\r","\r","        $ts = strtotime($str);\r","        if($ts === false) \r","            return;\r","        \r","        if($use_time)    \r","            return date($this-\u003edatetime_in, $ts);\r","        else\r","            return date($this-\u003edate_in, $ts);\r","\r","    }\r","\r","\r","    function date_out($str, $use_time = false){\r","\r","        // purpose: convert database format to local format\r","\r","        if(!isset($str) || mb_strlen($str) \u003c 8)\r","            return; \r","        \r","        if($use_time)\r","            return date($this-\u003edatetime_out, strtotime($str));\r","        else\r","            return date($this-\u003edate_out, strtotime($str));\r","\r","    }\r","\r","\r","    function format_title($field_name, $friendly_name = ''){\r","        \r","        // purpose: change field name to friendly. example: first_name becomes \"First Name\" or EntryFee1 becomes \"Entry Fee 1\"\r","        // returns: html escaped string\r","\r","        if(strlen($friendly_name ?? '') \u003e 0)\r","            return $this-\u003eclean_out($friendly_name);\r","\r","        $friendly_name = $field_name;\r","        $friendly_name = preg_replace('/([a-z]{1})([A-Z]{1})/', '\\1 \\2', $friendly_name);\r","        $friendly_name = preg_replace('/([a-z]{1})([0-9]+)/i', '\\1 \\2 ', $friendly_name);\r","        $friendly_name = str_replace('_', ' ', $friendly_name);\r","        $friendly_name = mb_convert_case($friendly_name, MB_CASE_TITLE, $this-\u003echarset);\r","\r","        return $this-\u003eclean_out($friendly_name);\r","\r","    }\r","\r","\r","    function get_action(){\r","\r","        // purpose: get the action/command on what function to call\r","        // submit buttons can be named with the action i.e. \"__update\" or \"__delete\";\r","        // look at the names/key posted to see if there's an action requested\r","\r","        static $action;\r","\r","        if(isset($action))\r","            return $action;\r","\r","        $post_get = array();\r","\r","        // merge post and get\r","        if(isset($_POST))\r","            $post_get = $_POST; \r","\r","        if(isset($_GET))\r","            $post_get = array_merge($post_get, $_GET);\r","\r","        if(isset($post_get['action']))\r","            return $post_get['action'];\r","\r","        foreach($post_get as $key =\u003e $val)\r","            if(mb_substr($key, 0, 2) == '__')\r","                return mb_substr($key, 2);\r","\r","    }\r","\r","\r","    function get_input_control($column_name, $value, $control, $called_from, \u0026$validate = array()){\r","\r","        // purpose: render html input based \"command\", if command is then try to call a user function\r","        // returns: html \r","\r","        $type = 'text'; // default\r","        $sql = '';\r","        $sql_param = '';\r","        if(isset($control['type'])){\r","            $type = $control['type'];\r","            $sql = $control['sql'] ?? ''; // optional\r","            $sql_param = $control['sql_param'] ?? ''; // optional\r","        }\r","\r","        // subtle backward compatible madness\r","        $legacy_control = $control;\r","        if(isset($control['legacy_control']))\r","            $legacy_control = $control['legacy_control'];\r","\r","        // set input size    \r","        if($called_from == 'grid')\r","            $size = $this-\u003egrid_text_input_size;\r","        else\r","            $size = $this-\u003eform_text_input_size;\r","\r","        $class = $this-\u003eget_class_name($column_name); \r","\r","        $validate_error_msg = ''; // error next to input\r","        $validate_tip = '';       // placeholder next to input for some inputs\r","\r","        // text, password, textarea only - placeholder depending on settings, inside or outside the input\r","        $validate_placeholder = '';\r","        $validate_placeholder_alternative = '';\r","\r","        // display tip or error next to input, not both\r","        if(($validate[$column_name]['result'] ?? null) === false)\r","            $validate_error_msg = \"\u003cspan class='lm_validate_error'\u003e\" . $this-\u003eclean_out($validate[$column_name]['error_msg']) . \"\u003c/span\u003e\";\r","        elseif(isset($validate[$column_name]['placeholder']) \u0026\u0026 strlen($validate[$column_name]['placeholder']) \u003e 0)\r","            $validate_tip = \"\u003cspan class='lm_validate_tip'\u003e\" . $this-\u003eclean_out($validate[$column_name]['placeholder']) . \"\u003c/span\u003e\";\r","\r","        // always try to get a placeholder for the text inputs\r","        if($this-\u003evalidate_tip_in_placeholder)\r","            $validate_placeholder = $this-\u003eclean_out($validate[$column_name]['placeholder'] ?? ''); // placeholders for text \r","        elseif(strlen($validate_error_msg) == 0)\r","            $validate_placeholder_alternative = \"\u003cspan class='lm_validate_tip'\u003e\" . $this-\u003eclean_out($validate[$column_name]['placeholder']) . \"\u003c/span\u003e\";\r","    \r","        $max_length = '';\r","        if(intval($this-\u003etext_input_max_length[$column_name] ?? '') \u003e 0)\r","            $max_length = \"maxlength='\" . $this-\u003etext_input_max_length[$column_name] . \"'\";\r","        elseif($this-\u003etext_input_max_length_default \u003e 0)\r","            $max_length = \"maxlength='\" . $this-\u003etext_input_max_length_default . \"'\";\r","\r","        if($type == 'text')\r","            return \"\u003cinput type='text' name='$column_name' class='$class' value='\" . $this-\u003eclean_out($value) . \"' size='$size' $max_length placeholder='$validate_placeholder'\u003e$validate_error_msg $validate_placeholder_alternative\";\r","        elseif($type == 'password')\r","            return \"\u003cinput type='password' name='$column_name' class='$class' value='\" . $this-\u003eclean_out($value) . \"' size='$size' $max_length placeholder='$validate_placeholder'\u003e$validate_error_msg $validate_placeholder_alternative\";\r","        elseif($type == 'number')\r","            return \"\u003cinput type='text' name='$column_name' class='$class' value='\" . $this-\u003eclean_out($value) . \"' size='18' $max_length placeholder='$validate_placeholder'\u003e$validate_error_msg $validate_placeholder_alternative\";\r","        elseif($type == 'date')\r","            return \"\u003cinput type='text' name='$column_name' class='$class' value='\" . $this-\u003edate_out($value) . \"' size='18' $max_length placeholder='$validate_placeholder'\u003e$validate_error_msg $validate_placeholder_alternative\";\r","        elseif($type == 'datetime')\r","            return \"\u003cinput type='text' name='$column_name' class='$class' value='\" . $this-\u003edate_out($value, true) . \"' size='18' $max_length placeholder='$validate_placeholder'\u003e$validate_error_msg $validate_placeholder_alternative\";\r","        elseif($type == 'textarea')\r","            return \"\u003ctextarea name='$column_name' class='$class' cols='60' rows='6' placeholder='$validate_placeholder'\u003e\" . $this-\u003eclean_out($value) . \"\u003c/textarea\u003e$validate_error_msg $validate_placeholder_alternative\";\r","        elseif($type == 'readonly_datetime')\r","            return $this-\u003edate_out($value, true);\r","        elseif($type == 'readonly_date')\r","            return $this-\u003edate_out($value);\r","        elseif($type == 'readonly')\r","            return $this-\u003eclean_out($value);\r","        elseif($type == 'image')\r","            return $this-\u003ehtml_image_input($column_name, $value) . $validate_tip . $validate_error_msg;\r","        elseif($type == 'document')\r","            return $this-\u003ehtml_document_input($column_name, $value) . $validate_tip . $validate_error_msg;\r","        elseif($type == 'select')\r","            return $this-\u003ehtml_select($column_name, $value, $sql, $sql_param, '', $this-\u003eselect_first_option_blank, 0) . $validate_tip . $validate_error_msg;\r","        elseif($type == 'selectmultiple')\r","            return $this-\u003ehtml_select($column_name, $value, $sql, $sql_param, '', $this-\u003eselect_first_option_blank, 6) . $validate_tip . $validate_error_msg;\r","        elseif($type == 'radio')\r","            return $this-\u003ehtml_radio($column_name, $value, $sql, $sql_param) . $validate_tip . $validate_error_msg;\r","        elseif($type == 'checkbox')\r","            return $this-\u003ehtml_checkbox($column_name, $value, $sql, $sql_param) . $validate_tip . $validate_error_msg;\r","        elseif(is_callable($type))\r","            return call_user_func($type, $column_name, $value, $legacy_control, $called_from, $validate_placeholder) . $validate_tip . $validate_error_msg;\r","        else\r","            $this-\u003edisplay_error(\"Input command or user function not found: $type\", 'get_input_control()');\r","\r","    }\r","\r","\r","    function get_output_control($column_name, $value, $control, $called_from){\r","\r","        // purpose: render html output based \"command\", if command is then try to call a user function\r","        // returns: html \r","\r","        $type = 'text'; // default\r","        if(isset($control['type']))\r","            $type = $control['type'];\r","\r","        // subtle backward compatible madness\r","        $legacy_control = $control;\r","        if(isset($control['legacy_control']))\r","            $legacy_control = $control['legacy_control'];\r","\r","        if($type == 'text')\r","            return $this-\u003eclean_out($value, $this-\u003egrid_ellipse_at); \r","        elseif($type == 'date')\r","            return $this-\u003edate_out($value); \r","        elseif($type == 'datetime')\r","            return $this-\u003edate_out($value, true); \r","        elseif($type == 'email')\r","            return \"\u003ca href='mailto:$value'\u003e$value\u003c/a\u003e\";\r","        elseif($type == 'document')\r","            return $this-\u003ehtml_document_output($value);\r","        elseif($type == 'image')\r","            return $this-\u003ehtml_image_output($value);\r","        elseif($type == 'html')\r","            return $this-\u003ehtml_html_output($value);\r","        elseif(is_callable($type))\r","            return call_user_func($type, $column_name, $value, $legacy_control, $called_from);\r","        else\r","            $this-\u003edisplay_error(\"Output command or user function not found: $type. Be sure to prefix control type with 2 dashes --\", 'get_output_control()');\r","\r","    }\r","\r","    \r","    function get_columns($context = ''){\r","\r","        // purpose: make array of column names from table name or custom sql \r","        // populates: grid_output_control or form_input_control\r","        // context options: form, grid, or blank/none\r","        // returns: number indexed array of column names\r","\r","        $table = $this-\u003etable;\r","        $sql = '';\r","        $sql_param = array();\r","\r","        if($context == 'grid'){\r","            $sql = $this-\u003egrid_sql;\r","            $sql_param = $this-\u003egrid_sql_param;\r","            if($sql == '')\r","                $sql = \"select *, `$this-\u003eidentity_name` from `$table`\";\r","        }\r","        elseif($context == 'form'){\r","            $sql = $this-\u003eform_sql;\r","            $sql_param = $this-\u003eform_sql_param;\r","        }\r","\r","        // no query defined, just make one\r","        if(strlen($sql) == 0){\r","\r","            if(mb_strlen($this-\u003etable) == 0)\r","                return $this-\u003edisplay_error(\"missing property: table\", 'get_columns');\r","\r","            $sql = \"select * from `$table`\";\r","        }\r","\r","        // remove last semicolon        \r","        $sql = rtrim($sql, \"\\r\\n\\t; \");\r","\r","        // try to remove last 'order by'. we need to allow functions in order by and order by in subqueries\r","        $this-\u003emb_preg_match_all('/order\\s+by\\s/im', $sql, $matches, PREG_OFFSET_CAPTURE);\r","        if(count($matches) \u003e 0){\r","            $match = end($matches[0]);\r","            $sql = mb_substr($sql, 0, $match[1]);\r","        }\r","        $sql .= ' limit 0 '; // add limit, we don't need any data, just meta data\r","\r","        // run query, get statement handle\r","        $sth = $this-\u003equery($sql, $sql_param, 'get_columns()', true, true);\r","        if($sth === false)\r","            return;\r","\r","        $i = 0;\r","        $columns = array();\r","        while($column = $sth-\u003egetColumnMeta($i++))\r","            array_push($columns, $column['name']);\r","\r","        // quit now if there's nothing else to do\r","        if(!$this-\u003eauto_populate_controls)\r","            return $columns;\r","\r","        // populate form_input_control\r","        $i = 0;\r","        while($column = $sth-\u003egetColumnMeta($i++)){\r","            \r","            $type = mb_strtolower($column['native_type'] ?? 0);\r","            $column_name = $column['name'];\r","            if(array_key_exists($column_name, $this-\u003eform_input_control) || $column_name == $this-\u003eidentity_name)\r","                continue;\r","\r","            if($type == 'date')\r","                $this-\u003eform_input_control[$column_name]['type'] = 'date';\r","            elseif($type == 'datetime' || $type == 'timestamp')\r","                $this-\u003eform_input_control[$column_name]['type'] = 'datetime';\r","            elseif($type == 'blob')\r","                $this-\u003eform_input_control[$column_name]['type'] = 'textarea';\r","            elseif(mb_strstr($type, 'short') || mb_strstr($type, 'int') || mb_strstr($type, 'long') || mb_strstr($type, 'float') || mb_strstr($type, 'double') || mb_strstr($type, 'decimal'))\r","                $this-\u003eform_input_control[$column_name]['type'] = 'number';\r","\r","        }\r","\r","\r","        // populate grid_output_control with type date or datetime\r","        $i = 0;\r","        while($context == 'grid' \u0026\u0026 $column = $sth-\u003egetColumnMeta($i++)){\r","            \r","            $type = mb_strtolower($column['native_type'] ?? '0');\r","            $column_name = $column['name'];\r","            if(array_key_exists($column_name, $this-\u003egrid_output_control) || $column_name == $this-\u003eidentity_name)\r","                continue;\r","\r","            if($type == 'date')\r","                $this-\u003egrid_output_control[$column_name]['type'] = 'date';\r","            elseif($type == 'datetime' || $type == 'timestamp')\r","                $this-\u003egrid_output_control[$column_name]['type'] = 'datetime';\r","\r","        }\r","\r","        // populate default values - user must have read access to information_schema.columns, aliases added for mysql 8\r","        $sql = \"select column_name as 'column_name', column_default as 'column_default' from information_schema.columns where column_default != 'NULL' and column_default is not null and table_name = :table and table_schema = database()\";\r","        $sql_param = array(':table' =\u003e $table);\r","        $result = $this-\u003equery($sql, $sql_param, 'get_columns() - populate form_default_value');\r","        foreach($result as $row){\r","            \r","            if($context == 'form')\r","                if(!array_key_exists($row['column_name'], $this-\u003eform_default_value))\r","                    $this-\u003eform_default_value[$row['column_name']] = trim($row['column_default'], \"'\"); // weird, string values are quoted\r","\r","        }\r","\r","        return $columns;\r","\r","    }\r","\r","    \r","    function get_pagination($count, $limit, $_offset, $_pagination_off){\r","\r","        // purpose: pagination for grid\r","\r","        if($count \u003c= 0 || $limit \u003c= 0)\r","            return;\r","\r","        $get = $this-\u003eget_qs('_order_by,_desc,_search');\r","        $active_page = floor($_offset / $limit) + 1; \r","        $total_page = ceil($count / $limit);\r","        $uri_path = $this-\u003eget_uri_path();\r","\r","\r","        $use_paging_link = '';\r","        if($_pagination_off == 1)\r","            $use_paging_link = \"\u003ca href='{$uri_path}_pagination_off=0\u0026$get' rel='nofollow'\u003e$this-\u003epagination_text_use_paging\u003c/a\u003e\";\r","\r","        if($_pagination_off == 1 || $count \u003c= $limit) \r","            return number_format($count) . \" $this-\u003epagination_text_records $use_paging_link\";\r","\r","        // simple text input for page number on giant datasets. use drop-down for smaller datasets.\r","        if($count \u003e 100000){\r","            $input = \"\u003cinput type='text' size='7' class='lm_active_page' value='$active_page' onkeyup='document.getElementsByClassName(\\\"lm_active_page\\\")[0].value = this.value; // send data to first input' \u003e \u003cinput type='button' class='lm_button' value='$this-\u003epagination_text_go' onclick='window.location.href=\\\"{$uri_path}_offset=\\\" + ((document.getElementsByClassName(\\\"lm_active_page\\\")[0].value * $limit) - $limit) + \\\"\u0026$get\\\"'\u003e\";\r","        }\r","        else\r","        {\r","            $input = \"\u003cselect onchange='window.location.href=\\\"{$uri_path}_offset=\\\" + this.options[this.selectedIndex].value + \\\"\u0026$get\\\"'\u003e\";\r","            for($i = 0, $p = 1; $i \u003c $count; $i += $limit, $p++){\r","                $sel = '';\r","                if($p == $active_page)\r","                    $sel .= \"selected='selected'\";\r","\r","                $input .= \"\u003coption value='$i' $sel\u003e$p\u003c/option\u003e\";\r","            }\r","            $input .= \"\u003c/select\u003e\";\r","        }        \r","\r","        $pagination = \"$this-\u003epagination_text_page: $input $this-\u003epagination_text_of $total_page \u0026nbsp; \";\r","        \r","        if($_offset == 0)\r","            $pagination .= \" $this-\u003epagination_text_back \";\r","        else\r","            $pagination .= \" \u003ca href='{$uri_path}_offset=\" . ($_offset - $limit) . \"\u0026$get'\u003e$this-\u003epagination_text_back\u003c/a\u003e \";\r","\r","        if($active_page \u003e= $total_page)\r","            $pagination  .= \" $this-\u003epagination_text_next \";\r","        else\r","            $pagination  .= \" \u003ca href='{$uri_path}_offset=\" . ($_offset + $limit) . \"\u0026$get'\u003e$this-\u003epagination_text_next\u003c/a\u003e \";\r","\r","        $pagination .= \" \u0026nbsp; \" . number_format($count) . \" $this-\u003epagination_text_records \u003ca href='{$uri_path}_pagination_off=1\u0026$get' rel='nofollow'\u003e$this-\u003epagination_text_show_all\u003c/a\u003e \";\r","\r","        return $pagination;\r","\r","    }\r","\r","    \r","    function get_qs($query_string_list = '_order_by,_desc,_offset,_search,_pagination_off'){\r","\r","        // purpose: render querysting. user selections for order, search, and page are carry from page to page. \r","        // this maintains search state while paging, updating, etc...\r","\r","        // append users additions\r","        if(mb_strlen($this-\u003equery_string_list) \u003e 0)\r","            $query_string_list .= ',' . $this-\u003equery_string_list;\r","\r","        $get = '';\r","        $arr = explode(',', trim($query_string_list, ','));\r","        foreach($arr as $key){\r","\r","            $val = '';\r","            if(isset($_REQUEST[$key]))\r","                $val = $_REQUEST[$key];\r","\r","            if(is_string($val) \u0026\u0026 mb_strlen($val) == 0)\r","                continue;\r","\r","            if(is_string($val))\r","                $get .= '\u0026' . urlencode($key) . '=' . urlencode($val);\r","\r","            if(is_array($val))\r","                foreach($val as $v)\r","                    $get .= '\u0026' . urlencode($key . '[]') . '=' . urlencode($v);\r","        }\r","\r","        return ltrim($get, '\u0026');\r","\r","    }\r","\r","    \r","    function get_upload($columns, $table_name, $identity_name, $identity_id, $context = 'form', $field_index = ''){\r","\r","        // purpose: used in insert and update to handle files\r","        // returns: true on success, false on error\r","\r","        $upload_width = $this-\u003eupload_width;\r","        $upload_height = $this-\u003eupload_height;\r","        $upload_crop = $this-\u003eupload_crop;\r","        $thumb_width = $this-\u003ethumb_width;\r","        $thumb_height = $this-\u003ethumb_height;\r","        $thumb_crop = $this-\u003ethumb_crop;\r","        $notice = '';\r","\r","        if($context == 'grid')\r","            $input_control = $this-\u003egrid_input_control;\r","        else\r","            $input_control = $this-\u003eform_input_control;\r","\r","        foreach($columns as $column_name){\r","\r","            $type = $input_control[$column_name]['type'] ?? '';\r","\r","            // uploads only\r","            if(!$this-\u003eis_upload($input_control, $column_name))\r","                continue;\r","\r","            // inputs are named differently on grids\r","            $input_name = $column_name;\r","            if($context != 'form')\r","                if(mb_strlen($field_index) \u003e 0)\r","                    $input_name = \"$column_name-0\"; // inserting\r","                else\r","                    $input_name = \"$column_name-$identity_id\"; // updating \r","\r","            if(!file_exists($this-\u003eget_upload_path()) \u0026\u0026 mb_strlen($this-\u003eget_upload_path()) \u003e 0){\r","                mkdir($this-\u003eget_upload_path(), 0755);\r","                usleep(500);\r","            }\r","\r","            if(!file_exists($this-\u003eget_thumb_path()) \u0026\u0026 mb_strlen($this-\u003eget_thumb_path()) \u003e 0){\r","                mkdir($this-\u003eget_thumb_path(), 0755);\r","                usleep(500);\r","            }\r","\r","            // process file deletion requested by checkbox with field_name + \"-delete\"\r","            if(($_POST[$input_name . '-delete'] ?? 0) == 1)\r","                $this-\u003eupload_delete($table_name, $identity_name, $identity_id, $column_name, $input_control);\r","\r","            // see if a new file was uploaded\r","            $file_name = $this-\u003eupload_file($input_name, $notice, $field_index);\r","\r","            // reloop - no new file uploaded\r","            if(!isset($file_name) || mb_strlen($file_name) == 0)\r","                continue;\r","                \r","            // delete previous existing file\r","            $this-\u003eupload_delete($table_name, $identity_name, $identity_id, $column_name, $input_control);\r","\r","            // copy upload to thumbnail path\r","            if(mb_strlen($this-\u003eget_thumb_path()) \u003e 0 \u0026\u0026 $type == 'image')\r","                if(!copy($this-\u003eget_upload_path() . \"/$file_name\", $this-\u003eget_thumb_path() . \"/$file_name\")){\r","                    $this-\u003edisplay_error(\"Unable to copy uploaded to thumb_path. Make sure path: \" . $this-\u003eget_thumb_path() . \" exists and is writeable. Try chmod 0755 (or 0777 if you must) on the destination path.\", 'get_upload()');\r","                    return false;\r","                }\r","\r","            // resize or crop main image\r","            if($type == 'image')\r","                if($upload_crop)\r","                    $this-\u003eimage_crop($this-\u003eget_upload_path() . \"/$file_name\", $upload_width, $upload_height);\r","                else\r","                    $this-\u003eimage_resize($this-\u003eget_upload_path() . \"/$file_name\", $upload_width, $upload_height);\r","\r","            // thumbs - resize or crop \r","            if($type == 'image' \u0026\u0026 mb_strlen($this-\u003eget_thumb_path()) \u003e 0)\r","                if($thumb_crop)\r","                    $this-\u003eimage_crop($this-\u003eget_thumb_path() . \"/$file_name\", $thumb_width, $thumb_height);\r","                else\r","                    $this-\u003eimage_resize($this-\u003eget_thumb_path() . \"/$file_name\", $thumb_width, $thumb_height);\r","\r","            // update file name in table \r","            $sql_param = array();\r","            $sql = \"update `$table_name` set `$column_name` = :file_name where `$identity_name` = :identity_id\";\r","            $sql_param[':file_name'] = $file_name;\r","            $sql_param[':identity_id'] = $identity_id;\r","            if($this-\u003equery($sql, $sql_param, 'get_upload()') === false)\r","                return false;\r","\r","        }\r","\r","        if(mb_strlen($notice) \u003e 0){\r","            $this-\u003edisplay_error($notice, 'get_upload()');\r","            return false;\r","        }\r","\r","        return true;\r","\r","    }\r","\r","\r","    function upload_file($input_name, \u0026$notice, $field_index = ''){\r","\r","        // purpose: upload file and return file name as a string\r","        // returns: file name on success, errors sent back by reference to $notice\r","\r","         // make regex pattern for extension validation from allow list. it should end up looking like this: /(.\\.mp3)|(.\\.pdf)$/i\r","        $pattern = '';\r","        $arr = preg_split('/\\s+/', $this-\u003eupload_allow_list);\r","        foreach($arr as $val)\r","            $pattern .= '(.' . preg_quote($val) . ')|';\r","\r","        $pattern = '/' . rtrim($pattern, '|') . '$/i'; \r","\r","        // get file info\r","        if(mb_strlen($field_index) \u003e 0){\r","            $size = intval($_FILES[$input_name]['size'][$field_index] ?? 0);\r","            $tmp_name = $_FILES[$input_name]['tmp_name'][$field_index] ?? '';\r","            $file_name = $this-\u003eclean_file_name($_FILES[$input_name]['name'][$field_index] ?? '');\r","        }\r","        else{\r","            $size = intval($_FILES[$input_name]['size'] ?? 0);\r","            $tmp_name = $_FILES[$input_name]['tmp_name'] ?? '';\r","            $file_name = $this-\u003eclean_file_name($_FILES[$input_name]['name'] ?? '');\r","        }\r","\r","        // nothing to do\r","        if($size \u003c= 0 || mb_strlen($file_name) == 0)\r","            return;\r","        \r","        if(mb_strlen($file_name) \u003e 250){\r","            $notice .= \"File name is too long.\\n\";\r","            return;\r","        }\r","\r","        if(!preg_match($pattern, $file_name)){\r","            $notice .= \"Invalid file type. Only the following documents and media types are allowed: $this-\u003eupload_allow_list\\n\";\r","            return;\r","        }\r","\r","        $file_name = $this-\u003eupload_rename_if_exists($this-\u003eget_upload_path(), $file_name);\r","\r","        if(!move_uploaded_file($tmp_name, $this-\u003eget_upload_path() . \"/$file_name\")){\r","            $notice .= \"Unable to move uploaded file. Make sure path: \" . $this-\u003eget_upload_path() . \" exists and is writeable. Try chmod 0755 (or 0777 is you must) on the destination path.\\n\";\r","            return;\r","        }\r","\r","        return $file_name;\r","\r","    }\r","\r","    \r","    function upload_delete($table_name, $identity_name, $identity_id, $field_name = '*', $input_control = array()){\r","\r","        // purpose: delete uploaded files, called from get_upload()\r","        // returns: true on success or false on error\r","\r","        $identity_id = $this-\u003ecast_id($identity_id);\r","\r","        if($field_name != '*')\r","            $field_name = \"`$field_name`\";\r","\r","\r","        // get 1 row of data\r","        $sql_param = array(':identity_id' =\u003e $identity_id);\r","        $sql = \"select $field_name from `$table_name` where `$identity_name` = :identity_id\";\r","        $result = $this-\u003equery($sql, $sql_param, 'upload_delete()');\r","\r","        if(!is_array($result))\r","            $result = array();\r","\r","        if(count($result) == 0){\r","            $this-\u003edisplay_error('Unable to locate record.', 'upload_delete()');\r","            return false;\r","        }\r","\r","        // loop thru fields\r","        $row = $result[0];\r","        foreach($row as $column_name =\u003e $val){\r","\r","            if(!isset($val) || mb_strlen($val) == 0)\r","                continue;\r","\r","            // uploads only\r","            if(!$this-\u003eis_upload($input_control, $column_name))\r","                continue;\r","\r","            // delete files\r","            if(mb_strlen($this-\u003eget_upload_path()) \u003e 0)\r","                @unlink($this-\u003eget_upload_path() . \"/$val\");\r","\r","            if(mb_strlen($this-\u003eget_thumb_path()) \u003e 0)\r","                @unlink($this-\u003eget_thumb_path() . \"/$val\");\r","                    \r","            // empty field now that file is deleted\r","            $sql = \"update `$table_name` set `$column_name` = null where `$identity_name` = :identity_id;\";\r","            $result = $this-\u003equery($sql, $sql_param, 'upload_delete()');                \r","            if($result === false)\r","                return false;\r","                \r","        }\r","    \r","        return true;\r","    \r","    }\r","\r","\r","    function upload_rename_if_exists($path, $file_name){\r","\r","        // purpose: return a new file name if file exists; foo.pdf returns foo_2.pdf then foo_3.pdf, etc...\r","        \r","        while(file_exists(\"$path/$file_name\")){\r","\r","            $number = 2;\r","\r","            $ext = pathinfo($file_name, PATHINFO_EXTENSION);\r","            $prefix = mb_substr($file_name, 0, mb_strlen($file_name) - mb_strlen($ext) - 1);\r","\r","            // extract and increment number at the end of the prefix\r","            preg_match('/_([0-9]+)$/', $prefix, $matches);\r","            if(count($matches) == 2){\r","                $prefix = mb_substr($prefix, 0, mb_strlen($prefix) - mb_strlen($matches[0]));\r","                $number = $matches[1];\r","                $number++;\r","            }\r","\r","            $file_name = \"{$prefix}_{$number}.{$ext}\";\r","\r","        }    \r","\r","        return $file_name;\r","\r","    }\r","\r","\r","    function get_upload_path(){\r","\r","        // purpose: return the path, prefer the absolute path if available\r","        // returns: string path\r","    \r","        if(strlen($this-\u003eupload_path_absolute))\r","            return rtrim($this-\u003eupload_path_absolute, '\\/');\r","\r","        return rtrim($this-\u003eupload_path, '\\/');\r","    }\r","\r","\r","    function get_thumb_path(){\r","\r","        // purpose: return the path, prefer the absolute path if available\r","        // returns: string path to thumbnail folder\r","\r","        if(strlen($this-\u003ethumb_path_absolute))\r","            return rtrim($this-\u003ethumb_path_absolute, '\\/');\r","\r","        return rtrim($this-\u003ethumb_path, '\\/');\r","    }\r","\r","\r","    function image_resize($file_name, $max_width, $max_height, $output_to_browser = false){\r","\r","        // purpose: resize image but keep orignal aspect ratio.  if output_to_browser = false, then file is altered and saved. \r","        // returns: nothing \r","\r","        if(!function_exists('imagecreatetruecolor'))\r","            die(\"Error: GD module must be installed in php for image resize/cropping\");\r","\r","        $this-\u003eimage_exif_rotate($file_name);\r","\r","        $ext = mb_strtolower(pathinfo($file_name, PATHINFO_EXTENSION));\r","\r","        if(!($ext == 'jpg' || $ext == 'jpeg' || $ext == 'gif' || $ext == 'png'))\r","            return;\r","\r","        list($orig_width, $orig_height) = getimagesize($file_name);\r","\r","        // invalid image or nothing to do\r","        if($orig_width == 0 || $orig_height == 0 || $max_width == 0 || $max_height == 0)\r","            return;            \r","\r","        // image is already smaller than maximum size\r","        if($orig_width \u003c= $max_width \u0026\u0026 $orig_height \u003c= $max_height)\r","            return;            \r","\r","        $width = $orig_width;\r","        $height = $orig_height;\r","\r","        // taller\r","        if($height \u003e $max_height){\r","            $width = ($max_height / $height) * $width;\r","            $height = $max_height;\r","        }\r","\r","        // wider\r","        if($width \u003e $max_width){\r","            $height = ($max_width / $width) * $height;\r","            $width = $max_width;\r","        }\r","\r","        $image_p = @imagecreatetruecolor($width, $height);\r","\r","        if($ext == 'gif')\r","            $image = @imagecreatefromgif($file_name);\r","        elseif($ext == 'png')\r","            $image = @imagecreatefrompng($file_name);\r","        else\r","            $image = @imagecreatefromjpeg($file_name);\r","\r","        @imagecopyresampled($image_p, $image, 0, 0, 0, 0, $width, $height, $orig_width, $orig_height);\r","\r","        if($output_to_browser){\r","\r","            if($ext == 'gif'){\r","                header('Content-type: image/gif');\r","                @imagegif($image_p);\r","            }\r","            elseif($ext == 'png'){\r","                header('Content-type: image/png');\r","                @imagepng($image_p);\r","            }\r","            else{\r","                header('Content-type: image/jpeg');\r","                @imagejpeg($image_p, '', $this-\u003eimage_quality); \r","            }\r","        \r","        }\r","        else{\r","\r","            if($ext == 'gif')\r","                @imagegif($image_p, $file_name);\r","            elseif($ext == 'png')\r","                @imagepng($image_p, $file_name);\r","            else\r","                @imagejpeg($image_p, $file_name, $this-\u003eimage_quality); \r","\r","        }\r","\r","    }\r","\r","\r","    function image_crop($file_name, $desired_width, $desired_height, $output_to_browser = false){\r","\r","        // purpose: crop image changes aspect ratio to match the requested dimensions. if output_to_browser = false, then file is altered and saved. \r","        // returns: nothing\r","\r","        if(!function_exists('imagecreatetruecolor'))\r","            die(\"Error: GD must be installed for image resize/cropping\");\r","\r","        $this-\u003eimage_exif_rotate($file_name);\r","\r","        $ext = mb_strtolower(pathinfo($file_name, PATHINFO_EXTENSION));\r","\r","        if(!($ext == 'jpg' || $ext == 'jpeg' || $ext == 'gif' || $ext == 'png'))\r","            return;\r","\r","        // get new dimensions\r","        list($width, $height) = getimagesize($file_name);\r","\r","        // nothing to do\r","        if($height == 0 || $width == 0 || $desired_height == 0 || $desired_width == 0)\r","            return;\r","\r","        // nothing to do\r","        if($height == $desired_height \u0026\u0026 $width == $desired_width \u0026\u0026 $output_to_browser == false)\r","            return;\r","\r","        if($desired_width / $desired_height \u003e $width / $height){\r","            $new_width = $desired_width;\r","            $new_height = $height * ($desired_width / $width);\r","        }\r","        else{\r","            $new_width = $width * ($desired_height / $height);\r","            $new_height = $desired_height;\r","        }\r","\r","        // resize\r","        $image_p = @imagecreatetruecolor($new_width, $new_height);\r","        $image_f = @imagecreatetruecolor($desired_width, $desired_height);\r","\r","        if($ext == 'png')\r","            $image = @imagecreatefrompng($file_name);    \r","        elseif($ext == 'gif')\r","            $image = @imagecreatefromgif($file_name);    \r","        else\r","            $image = @imagecreatefromjpeg($file_name);\r","\r","        @imagecopyresampled($image_p, $image, 0, 0, 0, 0, $new_width, $new_height, $width, $height);\r","\r","        // top center cropping\r","        $x = ($new_width - $desired_width) / 2;\r","        $y = ($new_height - $desired_height) / 5;\r","\r","        @imagecopyresampled($image_f, $image_p, 0, 0, $x, $y, $desired_width, $desired_height, $desired_width,  $desired_height);\r","\r","        // save or output\r","        if($output_to_browser){\r","\r","            if($ext == 'gif'){\r","                header('Content-type: image/gif');\r","                @imagegif($image_f);\r","            }\r","            elseif($ext == 'png'){\r","                header('Content-type: image/png');\r","                @imagepng($image_f);\r","            }\r","            else{\r","                header('Content-type: image/jpeg');\r","                @imagejpeg($image_f, '', $this-\u003eimage_quality); \r","            }\r","        \r","        }\r","        else{\r","\r","            if($ext == 'gif')\r","                @imagegif($image_f, $file_name);\r","            elseif($ext == 'png')\r","                @imagepng($image_f, $file_name);\r","            else\r","                imagejpeg($image_f, $file_name, $this-\u003eimage_quality); \r","\r","        }\r","\r","    }\r","\r","\r","    function image_exif_rotate($file_name){\r","\r","        // purpose: stand-alone exif image rotation, used by image_crop() and image_resize()\r","\r","        // tough luck if imagerotate isn't with your gd\r","        if(!function_exists('imagerotate'))\r","            return;\r","\r","        $ext = mb_strtolower(pathinfo($file_name, PATHINFO_EXTENSION));\r","\r","        if(!($ext == 'jpg' || $ext == 'jpeg' || $ext == 'gif' || $ext == 'png'))\r","            return;\r","\r","        if($ext == 'png')\r","            $image = imagecreatefrompng($file_name);    \r","        elseif($ext == 'gif')\r","            $image = imagecreatefromgif($file_name);    \r","        else\r","            $image = imagecreatefromjpeg($file_name);\r","\r","        $arr = @exif_read_data($file_name);\r","\r","        $o = 0;\r","        if(isset($arr['Orientation']))\r","            $o = intval($arr['Orientation']);\r","\r","        // nothing to do\r","        if($o == 0)\r","            return;\r","\r","        if($o == 3 || $o == 4)\r","            $image = imagerotate($image, 180, 0);\r","        elseif($o == 5 || $o == 6)\r","            $image = imagerotate($image, -90, 0);\r","        elseif($o == 7 || $o == 8)\r","            $image = imagerotate($image, 90, 0);\r","\r","        if($o == 2 || $o == 4 || $o == 5 || $o == 7)\r","            imageflip($image, IMG_FLIP_HORIZONTAL);\r","\r","        if($ext == 'gif')\r","            imagegif($image, $file_name);\r","        elseif($ext == 'png')\r","            imagepng($image, $file_name);\r","        else\r","            imagejpeg($image, $file_name, $this-\u003eimage_quality); \r","\r","        unset($image);\r","        return;\r","    }\r","    \r","    \r","    function display_error($error, $source_function, $wrap_lm = false){\r","        \r","        // purpose: display errors to user\r","\r","        if(ini_get('display_errors') != \"1\")\r","            $error = \"message disabled - use ini_set('display_errors' 1); to display detailed information\";\r","\r","        // some errors need to be wrapped to get the css id\r","        $open = '';\r","        $close = '';\r","        if($wrap_lm){\r","            $open = \"\u003cdiv id='lm'\u003e\";\r","            $close = '\u003c/div\u003e';\r","        }\r","\r","        $msg = nl2br($this-\u003eclean_out(\"Error: $error\\nSent From: $source_function\"));\r","        echo \"$open\u003cdiv class='lm_error'\u003e$msg\u003c/div\u003e$close\" ;\r","\r","    }\r","\r","\r","    function query($sql, $sql_param = array(), $source_function = '', $display_error = true, $return_sth = false){\r","\r","        // purpose: wrapper for pdo db call\r","        // returns: returns array of results, an empty array for no results, or false on error\r","\r","        try {\r","\r","            if(!$this-\u003eset_names){\r","                $sth = $this-\u003edbh-\u003eprepare(\"set names $this-\u003echarset_mysql\");\r","                $sth-\u003eexecute();\r","                $this-\u003eset_names = true;\r","            }\r","\r","            $sth = $this-\u003edbh-\u003eprepare($sql);\r","\r","            // legacy php 7 error catch\r","            if(!$sth-\u003eexecute($sql_param)){\r","                $arr = $sth-\u003eerrorInfo();\r","                $error = $arr[0] . \" \" . $arr[2];\r","                if($display_error)\r","                    $this-\u003edisplay_error(\"$error\\n\\nsql: $sql\\narr_sql_param: \" . print_r($sql_param, true), $source_function, true);\r","\r","                error_log(\"$error $sql {$_SERVER['REQUEST_URI']} sent from $source_function\");\r","                return false;\r","            }\r","\r","        } \r","        catch(PDOException $e){  \r","\r","            $error = $e-\u003egetMessage();\r","            if($display_error)\r","                $this-\u003edisplay_error(\"$error\\n\\nsql: $sql\\narr_sql_param: \" . print_r($sql_param, true), $source_function, true);\r","\r","            error_log($e);\r","            return false;\r","        }\r","\r","\r","        if($return_sth)\r","            return $sth;\r","\r","        if(preg_match('/^insert/i', ltrim($sql)))\r","            return $this-\u003ecast_id($this-\u003edbh-\u003elastInsertId());\r","\r","        if($sth-\u003ecolumnCount() == 0)\r","            return array();    \r","\r","        return $sth-\u003efetchAll(PDO::FETCH_ASSOC);\r","\r","    }\r","\r","\r","    private function query_cache($sql, $sql_param, $source_function){\r","\r","        // purpose: try return cached result, used by html_select, html_checkbox and html_radio, might help on grid rendering \r","\r","        static $results = array();\r","        static $miss = 0;\r","        $max = 6;\r","        $cnt = count($results);\r","\r","        // things aren't working out, just run the query, skip searching cache\r","        if($miss \u003e $max)\r","            return $this-\u003equery($sql, $sql_param, $source_function);\r","\r","        // see if result already exists\r","        foreach($results as $arr){\r","\r","            if($arr['sql'] !== $sql)\r","                continue;\r","\r","            if(count(array_diff_assoc($arr['sql_param'], $sql_param)) !== 0)\r","                continue;\r","                    \r","            // hit/success\r","            return $arr['result'];\r","        }\r","\r","        $miss++;\r","        $result = $this-\u003equery($sql, $sql_param, $source_function);\r","\r","        // save to cache\r","        $results[] = array('sql' =\u003e $sql, 'sql_param' =\u003e $sql_param, 'result' =\u003e $result);\r","\r","        return $result;\r","\r","    }\r","\r","\r","    function safe_np($named_parameter){\r","\r","        // purpose: remove illegal characters from pdo named parameter (w/o colon).\r","        // returns: string\r","\r","        return preg_replace('/[^a-zA-Z0-9_]/', '', $named_parameter);\r","            \r","    }\r","\r","\r","    function mb_preg_match_all($ps_pattern, $ps_subject, \u0026$pa_matches, $pn_flags = PREG_PATTERN_ORDER, $pn_offset = 0, $ps_encoding = NULL){\r","\r","        // purpose: preg_match_all wrapper that returns the correct int for PREG_OFFSET_CAPTURE\r","\r","        if(is_null($ps_encoding))\r","            $ps_encoding = mb_internal_encoding();\r","\r","        $pn_offset = strlen(mb_substr($ps_subject, 0, $pn_offset, $ps_encoding));\r","        $ret = preg_match_all($ps_pattern, $ps_subject, $pa_matches, $pn_flags, $pn_offset);\r","\r","        if($ret \u0026\u0026 ($pn_flags \u0026 PREG_OFFSET_CAPTURE))\r","            foreach($pa_matches as \u0026$ha_match)\r","                foreach($ha_match as \u0026$ha_match)\r","                    $ha_match[1] = mb_strlen(substr($ps_subject, 0, $ha_match[1]), $ps_encoding);\r","\r","        $pa_matches = array_filter($pa_matches); // php \u003c=5.3 returns array with 1 empty element on non-match, this will change to 0 element\r","\r","        return $ret;\r","\r","    }\r","\r","\r","    function redirect($url, $automatic = true){\r","\r","        // purpose: redirect user to url\r","        // returns: html redirect\r","        // if $automatic is false user has to click \"continue\" to proceed. \r","\r","        if($automatic === false){\r","            echo(\"\u003ccenter\u003e\u003ca href='$url'\u003eContinue\u003c/a\u003e\u003c/center\u003e\");    \r","            return;\r","        }\r","        \r","        // this feature is only used used with WordPress plugins - use a simple js redirect for WP\r","        if(mb_strlen($this-\u003euri_path) \u003e 0 || $this-\u003eredirect_using_js){\r","            echo \"\u003cscript\u003ewindow.location.href='$url';\u003c/script\u003e\u003cnoscript\u003e\u003ca href='$url'\u003eContinue\u003c/a\u003e\u003c/noscript\u003e\";\r","            return;\r","        }\r","\r","        // before calling header so any sessions changes are saved\r","        if(!isset($_SESSION))\r","            session_write_close();\r","\r","        // relative redirect\r","        if(!$this-\u003eabsolute_redirect){\r","            header(\"Location: $url\");\r","            die;\r","        }\r","\r","        // absolute redirect, will not work with port forwarding if server port is different from reverse proxy\r","        $port = '';    \r","        $host = preg_replace('/:[0-9]+$/', '', $_SERVER['HTTP_HOST']); // host without port number\r","        $protocol = 'http://';\r","        if($_SERVER['HTTPS'] ?? '' != '' \u0026\u0026 $_SERVER['HTTPS'] ?? '' != 'off')\r","            $protocol = 'https://';\r","        if(!($_SERVER['SERVER_PORT'] == '80' || $_SERVER['SERVER_PORT'] == '443'))\r","            $port = ':' . $_SERVER['SERVER_PORT'];\r","\r","        header(\"Location: $protocol$host$port$url\");\r","        die;\r","    \r","    }\r","\r","\r","    function get_uri_path(){\r","\r","        // purpose: get request uri without the querystring but with query delimiter. user can also specify a URI.\r","        // returns: uri path string\r","\r","        static $uri_path = false;\r","        \r","        // user defined uri\r","        if(mb_strlen($this-\u003euri_path) \u003e 0){\r","                \r","            if(mb_strstr($this-\u003euri_path, '?'))    \r","                $uri_path = $this-\u003euri_path . '\u0026'; // if user specifies URI, it may already have a ?\r","            else\r","                $uri_path = $this-\u003euri_path . '?';\r","        }\r","\r","        if($uri_path)\r","            return $uri_path;\r","\r","        $arr = parse_url($_SERVER['REQUEST_URI']);\r","        $uri_path = $arr['path'];\r","\r","        if($uri_path == '')\r","            $uri_path = '/';\r","\r","        $uri_path = $uri_path . '?';\r","\r","        return $uri_path;\r","\r","    }\r","\r","\r","    function get_class_name($input_name){\r","\r","        // purpose: generate class name from form input name; remove '-id' or '[]' suffix \r","        // returns: string    \r","\r","        return 'lm_' . preg_replace('/(-[0-9]+)|(\\[\\])$/', '', $input_name);\r","\r","    }\r","\r","\r","    function is_upload(\u0026$input_control, \u0026$column_name){\r","\r","        // purpose: see if column is an upload type\r","        // returns: boolean\r","\r","        foreach($input_control as $col =\u003e $ctrl)\r","            if($col == $column_name \u0026\u0026 strstr('image,document', $ctrl['type']))\r","                return true;\r","\r","        return false;\r","\r","    }\r","\r","    \r","    function export(\u0026$result, $columns){\r","\r","        // purpose: send database result in CSV format to browser. \r","\r","        if(mb_strlen($this-\u003eexport_csv_file_name) \u003e 0)\r","            $file_name = $this-\u003eexport_csv_file_name;\r","        elseif(mb_strlen($this-\u003etable) \u003e 0)\r","            $file_name = $this-\u003eclean_file_name($this-\u003etable . '.csv');\r","        else\r","            $file_name = 'download.csv';\r","\r","        // output buffering required\r","        $level = 0;\r","        $arr = ob_get_status(true);\r","        if($arr)\r","            $level = count($arr);\r","\r","        if($level \u003c= 0){\r","            $error = \"ob_start() or ob_start('ob_gzhandler') must be called at the beginning of the script to use CSV Export.\";\r","            $this-\u003edisplay_error($error, 'export()');\r","            return;\r","        }\r","\r","        // erase any existing buffers\r","        while($level \u003e= 1 ){\r","            ob_end_clean();\r","            $level--;\r","        }\r","\r","        if(!ob_start('ob_gzhandler'))\r","            ob_start();\r","\r","        header(\"Cache-Control: maxage=1\");\r","        header(\"Pragma: public\");\r","        header(\"Content-Type: application/csv\");\r","        header(\"Content-Disposition: attachment; filename=$file_name\");\r","        echo chr(0xEF).chr(0xBB).chr(0xBF); // bom here is reported to help\r","\r","        // remove last column if last column is the identity that holds the [edit] and [delete] links\r","        if(end($columns) == $this-\u003eidentity_name)\r","             array_pop($columns);\r","           \r","        // header row    \r","        $column_index = 0;\r","        foreach($columns as $key =\u003e $val)\r","            echo $this-\u003eexport_escape($val, $column_index++);\r","\r","        echo \"\\n\";\r","\r","        // loop thru data\r","        foreach($result as $row){\r","\r","            $column_index = 0;\r","            foreach($columns as $val)\r","                echo $this-\u003eexport_escape($row[$val], $column_index++);\r","\r","            echo \"\\n\";\r","            \r","        }\r","\r","        ob_end_flush();\r","        die();\r","\r","    }\r","\r","    \r","    function export_escape($str, $column_index){\r","\r","        // purpose: escape for export()\r","        // returns: separated and escaped string\r","\r","        $str = str_replace($this-\u003eexport_delim, $this-\u003eexport_delim_escape . $this-\u003eexport_delim, $str ?? '');\r","\r","        if($column_index == 0)\r","            return $this-\u003eexport_delim . $str . $this-\u003eexport_delim; \r","        else\r","            return $this-\u003eexport_separator . $this-\u003eexport_delim . $str . $this-\u003eexport_delim; \r","\r","    }\r","\r","\r","    function validate(\u0026$validate){\r","\r","        // purpose: run validation\r","        // return false if any input fails validation\r","        // alters the $validate array adding bool flag corresponding to column name\r","\r","        // $validate is an array of arrays\r","        // regexp  regular expression, 'email', or user defined function\r","        // error_msg optional\r","        // placeholder optional\r","        // optional, boolean is input optional?\r","        // result, boolean resutls are stored here\r","\r","        $columns = $this-\u003eget_columns('form');\r","        $all_valid = true;\r","\r","        foreach($columns as $column_name){\r","            \r","            $regexp_or_user_func = $validate[$column_name]['regexp'] ?? null;\r","            \r","            if(!isset($regexp_or_user_func))\r","                continue;\r","\r","            $val = $_POST[$column_name] ?? '';\r","            if(is_array($val))\r","                $val = implode($this-\u003edelim, $val);\r","            $val = trim($val);\r","\r","            // don't validate empty optional parameters\r","            if($validate[$column_name]['optional'] === true \u0026\u0026 $val == '')\r","                continue;\r","\r","            if($regexp_or_user_func == 'email')\r","                $is_valid = filter_var($val, FILTER_VALIDATE_EMAIL);\r","            elseif(mb_substr($regexp_or_user_func, 0, 1) != '/')\r","                $is_valid = call_user_func($regexp_or_user_func);\r","            else\r","                $is_valid = preg_match($regexp_or_user_func, $val);\r","\r","            $validate[$column_name]['result'] = (bool) $is_valid;\r","            \r","            // add error msg \r","            if(strlen($validate[$column_name]['error_msg']) == 0)\r","                $validate[$column_name]['error_msg'] = $this-\u003evalidate_text_general;\r","\r","            if(!$is_valid)\r","                $all_valid = false;\r","        }\r","\r","        return $all_valid;\r","\r","    }\r","\r","\r","    function modernize_control($control, $column_name){\r","\r","        // purpose: change control definition to new style, keep backward compatibility\r","        // returns array in new style format\r","        //  old style: 'select col_1, col_2 from table; --select'\r","        //  new style: array('type' =\u003e 'select', 'sql' =\u003e 'select id, text from table', 'sql_param' =\u003e array());\r","\r","        if(is_array($control)){\r","            if(isset($control['type']) \u0026\u0026 strlen($control['type']) \u003e 0)\r","                return $control;\r","            die(\"Error: control for $column_name appears to be invalid\");\r","        }\r","\r","        $pos = strrpos($control, '--');\r","        $sql = substr($control, 0, $pos);\r","        $type = trim(substr($control, $pos + 2));\r","        if($pos === false || strlen($type) == 0)\r","            die(\"Error: control for $column_name appears to be invalid\");\r","\r","        return array('type' =\u003e $type, 'sql' =\u003e $sql, 'sql_param' =\u003e null, 'legacy_control' =\u003e $control);\r","    }\r","\r","\r","    function modernize_validate($arr, $column_name){\r","\r","        // purpose: change validation ar